INSERT INTO _fields_wd1_plan (site_id, column_name, old_value, new_value, change_key, reason, evidence) VALUES
    ('c485a7c6-0006-4f6f-8dd7-f5f39a427d84'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s009-rollback:c485a7c6-0006-4f6f-8dd7-f5f39a427d84:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1 - 500 AD'' restored on Vicus Maracitanus-Ksar Toual', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('c485a7c6-0006-4f6f-8dd7-f5f39a427d84'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s009-rollback:c485a7c6-0006-4f6f-8dd7-f5f39a427d84:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''1'' restored on Vicus Maracitanus-Ksar Toual', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0140)", "decision": "clear", "status": "MISSING", "reasoning": "The Princeton Encyclopedia of Classical Sites calls the town unquestionably pre-Roman in origin without giving a date, while other pages date the visible remains to the 1st-2nd century AD and the Digital Atlas uses a generic start of -30; no two independent sources date the start of the site, so the field is emptied.", "value_page": null}]'::jsonb),
    ('c52fd25f-8ddf-4d21-a875-f5602d15b623'::uuid, 'period_name', NULL, '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s009-rollback:c52fd25f-8ddf-4d21-a875-f5602d15b623:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''500 BC - 1 AD'' restored on Careyeros Hill', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('c52fd25f-8ddf-4d21-a875-f5602d15b623'::uuid, 'period_start', NULL, '-500', 'fields-wd1-2026-09-26b-s009-rollback:c52fd25f-8ddf-4d21-a875-f5602d15b623:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-500'' restored on Careyeros Hill', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0094)", "decision": "clear", "status": "MISSING", "reasoning": "The only primary account (Megalithic Portal) is self-contradictory - ''at least as early as 200 BC'' but the architecture ''properly dated to the Post-Classic Period, or about 1200 AD'' - and Wikipedia''s ''c. 800 AD'' merely cites that page; no two independent sources date the start.", "value_page": null}]'::jsonb),
    ('c52fd25f-8ddf-4d21-a875-f5602d15b623'::uuid, 'site_type', NULL, 'City/town/settlement', 'fields-wd1-2026-09-26b-s009-rollback:c52fd25f-8ddf-4d21-a875-f5602d15b623:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''City/town/settlement'' restored on Careyeros Hill', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0094)", "decision": "clear", "status": "MISSING", "reasoning": "Only the Megalithic Portal describes the site (tagged ''Ancient Village or Settlement'' but described as a ridgetop observatory and ceremonial site); Wikipedia''s ''hilltop archaeological site'' is sourced from that page, so no two independent sources say what kind of site it is.", "value_page": null}]'::jsonb),
    ('c52fd25f-8ddf-4d21-a875-f5602d15b623'::uuid, 'source_url', 'https://www.megalithic.co.uk/Careyeros-Hill-18241', 'https://www.megalithic.co.uk/article.php?sid=18241', 'fields-wd1-2026-09-26b-s009-rollback:c52fd25f-8ddf-4d21-a875-f5602d15b623:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://www.megalithic.co.uk/article.php?sid=18241'' restored on Careyeros Hill', '[{"source": "https://www.megalithic.co.uk/Careyeros-Hill-18241", "url": "https://www.megalithic.co.uk/Careyeros-Hill-18241", "quote": "Careyeros Hill is an ancient ridgetop observatory and ceremonial site in the coastal hills of the state of Nayarit, Mexico.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Punta_Mita", "url": "https://en.wikipedia.org/wiki/Punta_Mita", "quote": "On the Punta Mita peninsula, a hilltop archaeological site known as Careyeros Hill has been dated to c. 800 AD.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0094)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article.php?sid=18241 URL is a 301 redirect to the entry''s own page https://www.megalithic.co.uk/Careyeros-Hill-18241, which is about this site; the Punta Mita article on Wikipedia names the same hilltop site on the Punta Mita peninsula.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('c54b1f6c-0870-401c-8857-5b4aac198056'::uuid, 'source_url', 'https://archiqoo.com/locations/bakka_temple.php', 'https://en.wikipedia.org/wiki/Bakka,_Lebanon', 'fields-wd1-2026-09-26b-s009-rollback:c54b1f6c-0870-401c-8857-5b4aac198056:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Bakka,_Lebanon'' restored on Bakka Roman Temple', '[{"source": "https://archiqoo.com/locations/bakka_temple.php", "url": "https://archiqoo.com/locations/bakka_temple.php", "quote": "The ruins of the temple are located in the village of Bakka in Beqaa Governorate in Lebanon", "outcome": "found"}, {"source": "https://books.openedition.org/ifpo/1458", "url": "https://books.openedition.org/ifpo/1458", "quote": "Les ruines d’un sanctuaire sont englobées dans le village de Bakka (1480 m d’altitude).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0092)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the village and municipality of Bakka; no Wikipedia article exists for the temple, and Archiqoo''s Bakka Temple page is about the temple itself, which Aliquot''s Ifpo catalogue independently describes within Bakka village.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('c5851dba-f3f4-4aaf-a4a1-37bf6a56600b'::uuid, 'period_name', NULL, '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s009-rollback:c5851dba-f3f4-4aaf-a4a1-37bf6a56600b:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''3000 - 1500 BC'' restored on Micheldever Wood', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('c5851dba-f3f4-4aaf-a4a1-37bf6a56600b'::uuid, 'period_start', NULL, '-3000', 'fields-wd1-2026-09-26b-s009-rollback:c5851dba-f3f4-4aaf-a4a1-37bf6a56600b:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-3000'' restored on Micheldever Wood', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0041)", "decision": "clear", "status": "MISSING", "reasoning": "The sources name only periods - Bronze Age remains, possible Neolithic finds, Iron Age enclosures and a Roman villa - and no source dates the start of the site with a year, century or millennium, so the stored -3000 is not attested.", "value_page": null}]'::jsonb),
    ('c5bc8249-97a6-4f75-bf35-6c04565d052f'::uuid, 'site_type', 'City', 'Temple complex', 'fields-wd1-2026-09-26b-s009-rollback:c5bc8249-97a6-4f75-bf35-6c04565d052f:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Temple complex'' restored on Avdat National Park', '[{"source": "https://en.wikipedia.org/wiki/Avdat", "url": "https://en.wikipedia.org/wiki/Avdat", "quote": "in their time becoming the most important city on the Incense Route after Petra", "outcome": "found"}, {"source": "https://nabataea.net/explore/cities_and_sites/obodat-avdat/", "url": "https://nabataea.net/explore/cities_and_sites/obodat-avdat/", "quote": "This ancient caravan station evolved into a large desert city known as Obodat", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0083)", "decision": "replace", "status": "CONFLICT", "reasoning": "The sources describe Avdat/Oboda as a Nabataean, Roman and Byzantine city (one of UNESCO''s Desert Cities of the Negev) whose acropolis temple is only one of its monuments, so City fits better than Temple complex.", "value_page": null}]'::jsonb),
    ('c5c5f2da-a5ea-41c6-807d-4c8ad7af03ba'::uuid, 'site_type', NULL, 'City/town/settlement', 'fields-wd1-2026-09-26b-s009-rollback:c5c5f2da-a5ea-41c6-807d-4c8ad7af03ba:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''City/town/settlement'' restored on Witham Shield', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0049)", "decision": "clear", "status": "CONFLICT", "reasoning": "The entry is an artefact (a bronze shield facing) and its place is only a river findspot (HER record type FINDSPOT); no source describes a settlement or any canonical site type, so the wrong ''City/town/settlement'' is emptied.", "value_page": null}]'::jsonb),
    ('c63b0df7-79e5-4734-bb99-b17ccd8f54eb'::uuid, 'geom', 'SRID=4326;POINT(-3.121304 54.454977)', '0101000020E6100000FEE0F0EEFB8208C0DB78D7903A394B40', 'fields-wd1-2026-09-26b-s009-rollback:c63b0df7-79e5-4734-bb99-b17ccd8f54eb:geom', 'rollback of fields-wd1-2026-09-26b-s009: geom ''0101000020E6100000FEE0F0EEFB8208C0DB78D7903A394B40'' restored on Langdale Axe Industry', '[{"source": "https://www.megalithic.co.uk/article.php?sid=6924", "url": "https://www.megalithic.co.uk/article.php?sid=6924", "quote": "Latitude: 54.454977N Longitude: 3.121304W", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/5042484794", "url": "https://www.openstreetmap.org/node/5042484794", "quote": "54.4559100, -3.1203686", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0039)", "decision": "replace", "status": "CONFLICT", "reasoning": "The axe factory''s main locus is the worked scree of Pike of Stickle; the Megalithic Portal places the Langdale Axe Factory at 54.454977N 3.121304W and OpenStreetMap maps the Langdale Axe Stone Quarry 0.1 km away, whereas the stored point (shared only by the Wikipedia/Wikidata family) lies about 3.9 km east in the Great Langdale valley floor, where no quarry is recorded.", "value_page": null}]'::jsonb),
    ('c63b0df7-79e5-4734-bb99-b17ccd8f54eb'::uuid, 'lat', '54.454977', '54.44709978600596', 'fields-wd1-2026-09-26b-s009-rollback:c63b0df7-79e5-4734-bb99-b17ccd8f54eb:lat', 'rollback of fields-wd1-2026-09-26b-s009: lat ''54.44709978600596'' restored on Langdale Axe Industry', '[{"source": "https://www.megalithic.co.uk/article.php?sid=6924", "url": "https://www.megalithic.co.uk/article.php?sid=6924", "quote": "Latitude: 54.454977N Longitude: 3.121304W", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/5042484794", "url": "https://www.openstreetmap.org/node/5042484794", "quote": "54.4559100, -3.1203686", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0039)", "decision": "replace", "status": "CONFLICT", "reasoning": "The axe factory''s main locus is the worked scree of Pike of Stickle; the Megalithic Portal places the Langdale Axe Factory at 54.454977N 3.121304W and OpenStreetMap maps the Langdale Axe Stone Quarry 0.1 km away, whereas the stored point (shared only by the Wikipedia/Wikidata family) lies about 3.9 km east in the Great Langdale valley floor, where no quarry is recorded.", "value_page": null}]'::jsonb),
    ('c63b0df7-79e5-4734-bb99-b17ccd8f54eb'::uuid, 'lon', '-3.121304', '-3.063957087255516', 'fields-wd1-2026-09-26b-s009-rollback:c63b0df7-79e5-4734-bb99-b17ccd8f54eb:lon', 'rollback of fields-wd1-2026-09-26b-s009: lon ''-3.063957087255516'' restored on Langdale Axe Industry', '[{"source": "https://www.megalithic.co.uk/article.php?sid=6924", "url": "https://www.megalithic.co.uk/article.php?sid=6924", "quote": "Latitude: 54.454977N Longitude: 3.121304W", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/5042484794", "url": "https://www.openstreetmap.org/node/5042484794", "quote": "54.4559100, -3.1203686", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0039)", "decision": "replace", "status": "CONFLICT", "reasoning": "The axe factory''s main locus is the worked scree of Pike of Stickle; the Megalithic Portal places the Langdale Axe Factory at 54.454977N 3.121304W and OpenStreetMap maps the Langdale Axe Stone Quarry 0.1 km away, whereas the stored point (shared only by the Wikipedia/Wikidata family) lies about 3.9 km east in the Great Langdale valley floor, where no quarry is recorded.", "value_page": null}]'::jsonb),
    ('c663e466-6644-4d97-9fb5-24d85eddb646'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s009-rollback:c663e466-6644-4d97-9fb5-24d85eddb646:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''4500 - 3000 BC'' restored on Rock Shelter of Solhapa', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('c663e466-6644-4d97-9fb5-24d85eddb646'::uuid, 'period_start', NULL, '-4000', 'fields-wd1-2026-09-26b-s009-rollback:c663e466-6644-4d97-9fb5-24d85eddb646:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-4000'' restored on Rock Shelter of Solhapa', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0118)", "decision": "clear", "status": "MISSING", "reasoning": "The heritage descriptions date the engravings only as late Neolithic to early Chalcolithic/Bronze Age without a year, and the one dated statement (All About Portugal, around 1500 BC) has no independent second source, so no two sources date the start.", "value_page": null}]'::jsonb),
    ('c663e466-6644-4d97-9fb5-24d85eddb646'::uuid, 'site_type', 'Rock art', 'Rock relief/carving', 'fields-wd1-2026-09-26b-s009-rollback:c663e466-6644-4d97-9fb5-24d85eddb646:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Rock relief/carving'' restored on Rock Shelter of Solhapa', '[{"source": "https://www.allaboutportugal.pt/en/miranda-do-douro/monuments/abrigo-rupestre-da-solhapa", "url": "https://www.allaboutportugal.pt/en/miranda-do-douro/monuments/abrigo-rupestre-da-solhapa", "quote": "Prehistoric rock shelters, where traces of wall representations are visible.", "outcome": "found"}, {"source": "https://www.rotaterrafria.com/ver/patrimonio/arqueologico/geo_artigo/abrigo-rupestre-da-solhapa", "url": "https://www.rotaterrafria.com/ver/patrimonio/arqueologico/geo_artigo/abrigo-rupestre-da-solhapa", "quote": "Abrigo rupestre da Solhapa (arte rupestre, Pré-história Recente, Imóvel de Interesse Público) - abrigo situado a cerca de três quilómetros da localidade de Duas Igrejas num ermo granítico, sobranceiro ao rio Douro.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Rock_shelter_of_Solhapa", "url": "https://en.wikipedia.org/wiki/Rock_shelter_of_Solhapa", "quote": "The iconographic diversity is great with dimples, perpendicular features, semicircles and straight and interconnected bars, almost labyrinthine.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0118)", "decision": "replace", "status": "CONFLICT", "reasoning": "Solhapa is a natural granite rock shelter whose ceiling, walls and floor carry prehistoric engravings (a ''sorcerer'' figure, cup-marks, serpentiform and labyrinthine motifs); All About Portugal, the Terra Fria municipal association (arte rupestre) and Wikipedia describe a decorated shelter, i.e. rock art rather than a sculpted relief.", "value_page": null}]'::jsonb),
    ('c6a4851c-3ff8-4e60-8744-356cb4040ba1'::uuid, 'period_name', '3000 - 1500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s009-rollback:c6a4851c-3ff8-4e60-8744-356cb4040ba1:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''4500 - 3000 BC'' restored on Glebe Cairn, Kilmartin Glen', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1700) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('c6a4851c-3ff8-4e60-8744-356cb4040ba1'::uuid, 'period_start', '-1700', '-4000', 'fields-wd1-2026-09-26b-s009-rollback:c6a4851c-3ff8-4e60-8744-356cb4040ba1:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-4000'' restored on Glebe Cairn, Kilmartin Glen', '[{"source": "https://en.wikipedia.org/wiki/Chambered_cairn", "url": "https://en.wikipedia.org/wiki/Chambered_cairn", "quote": "Glebe cairn in Kilmartin Glen in Argyll dates from 1700 BC", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=241", "url": "https://www.megalithic.co.uk/article.php?sid=241", "quote": "Glebe cairn was constructed between 2000 and 1500 BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0123)", "decision": "replace", "status": "MISSING", "reasoning": "Glebe Cairn is an Early Bronze Age cairn: Wikipedia dates it from 1700 BC and the Megalithic Portal to 2000-1500 BC, both in the 3000-1500 BC bucket, not the stored Neolithic 4500-3000 BC bucket.", "value_page": null}]'::jsonb),
    ('c6a4851c-3ff8-4e60-8744-356cb4040ba1'::uuid, 'source_url', 'https://nl.wikipedia.org/wiki/Glebe_Cairn', 'https://en.wikipedia.org/wiki/Kilmartin_Glen', 'fields-wd1-2026-09-26b-s009-rollback:c6a4851c-3ff8-4e60-8744-356cb4040ba1:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Kilmartin_Glen'' restored on Glebe Cairn, Kilmartin Glen', '[{"source": "https://nl.wikipedia.org/wiki/Glebe_Cairn", "url": "https://nl.wikipedia.org/wiki/Glebe_Cairn", "quote": "De Glebe Cairn is een grafheuvel (cairn) uit de bronstijd, gelegen in Kilmartin Glen in de Schotse regio Argyll and Bute.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=241", "url": "https://www.megalithic.co.uk/article.php?sid=241", "quote": "Glebe cairn was constructed between 2000 and 1500 BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0123)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the whole Kilmartin Glen; the cairn has no English article, but the Dutch Wikipedia has its own article on Glebe Cairn, which is preferred over a register page.", "value_page": {"lang": "nl", "problem": null, "resolved_title": "Glebe Cairn", "unreadable": false, "wikibase_item": "Q2307806"}}]'::jsonb),
    ('c6bd2d66-f54d-4d02-8b14-041414043cf3'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s009-rollback:c6bd2d66-f54d-4d02-8b14-041414043cf3:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1500 - 500 BC'' restored on Ladle Hill', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('c6bd2d66-f54d-4d02-8b14-041414043cf3'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s009-rollback:c6bd2d66-f54d-4d02-8b14-041414043cf3:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-1500'' restored on Ladle Hill', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0038)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia, the Megalithic Portal and the North Wessex Downs page call the unfinished hillfort Iron Age but give no year or century, and Wikipedia notes it has never been excavated; the Bronze Age barrows and linear ditches around it are separate, earlier features. No two sources date the fort''s start, so the field is emptied.", "value_page": null}]'::jsonb),
    ('c6bd2d66-f54d-4d02-8b14-041414043cf3'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s009-rollback:c6bd2d66-f54d-4d02-8b14-041414043cf3:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Fortress/citadel'' restored on Ladle Hill', '[{"source": "https://en.wikipedia.org/wiki/Ladle_Hill", "url": "https://en.wikipedia.org/wiki/Ladle_Hill", "quote": "This Iron Age fort is roughly rectangular and enclosed seven acres within an embankment and ditch.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=2239", "url": "https://www.megalithic.co.uk/article.php?sid=2239", "quote": "Unfinished Iron Age hillfort and Bronze Age barrows in Hampshire", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0038)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Megalithic Portal both describe the site as an unfinished Iron Age hillfort; nothing calls it a fortress or citadel, so the specific type is Fort.", "value_page": null}]'::jsonb),
    ('c6d9487d-d138-4d73-beb1-5735e50da048'::uuid, 'site_type', 'Aqueduct', 'City/town/settlement', 'fields-wd1-2026-09-26b-s009-rollback:c6d9487d-d138-4d73-beb1-5735e50da048:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''City/town/settlement'' restored on Jerwan', '[{"source": "https://mcid.mcah.columbia.edu/mapping-mesopotamian-monuments/jerwan-aqueduct", "url": "https://mcid.mcah.columbia.edu/mapping-mesopotamian-monuments/jerwan-aqueduct", "quote": "the aqueduct was highly advanced in its engineering and construction", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Jerwan", "url": "https://en.wikipedia.org/wiki/Jerwan", "quote": "The site is famous for the ruins of an enormous aqueduct crossing the Khenis River", "outcome": "found"}, {"source": "WD1 decision (counted, round 2, wd1-r2-b0002)", "decision": "replace", "status": "CONFLICT", "reasoning": "Columbia University''s Mapping Mesopotamian Monuments describes Jerwan as the Jerwan Aqueduct (site type Bridges and Aqueducts), and English Wikipedia says the site is famous for the ruins of an enormous aqueduct crossing the Khenis River; two independent sources describe it as an aqueduct, not as a city, town or settlement, so the stored type is replaced with Aqueduct.", "value_page": null}]'::jsonb),
    ('c70a32fa-651a-4a64-b09b-abd2bcf0974a'::uuid, 'period_name', '500 - 1000 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s009-rollback:c70a32fa-651a-4a64-b09b-abd2bcf0974a:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1 - 500 AD'' restored on Pyongyang Castle', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(552) = ''500 - 1000 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('c70a32fa-651a-4a64-b09b-abd2bcf0974a'::uuid, 'period_start', '552', '1', 'fields-wd1-2026-09-26b-s009-rollback:c70a32fa-651a-4a64-b09b-abd2bcf0974a:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''1'' restored on Pyongyang Castle', '[{"source": "https://contents.history.go.kr/mobile/mid/kc_r101010", "url": "https://contents.history.go.kr/mobile/mid/kc_r101010", "quote": "『삼국사기』에 따르면 양원왕 8년(552)에 장안성을 쌓고", "outcome": "found"}, {"source": "https://exploredprk.com/history/pyongyang-fortress/", "url": "https://exploredprk.com/history/pyongyang-fortress/", "quote": "Built between 552 and 586 CE, the fortress took full advantage of Pyongyang’s natural geography.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0100)", "decision": "replace", "status": "MISSING", "reasoning": "The National Institute of Korean History cites the Samguk sagi that Jangan Fortress (the walled city of Pyongyang) was built from the 8th year of King Yangwon (552), and Explore DPRK dates Pyongyang Fortress to 552-586 CE; the start 552 lies in 500 - 1000 AD, not the stored 1 - 500 AD bucket (the capital''s move of 427 went to an earlier site, Anhak Palace and Taesongsan).", "value_page": null}]'::jsonb),
    ('c70a32fa-651a-4a64-b09b-abd2bcf0974a'::uuid, 'site_type', 'Fortress', 'Castle/palace', 'fields-wd1-2026-09-26b-s009-rollback:c70a32fa-651a-4a64-b09b-abd2bcf0974a:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Castle/palace'' restored on Pyongyang Castle', '[{"source": "https://exploredprk.com/history/pyongyang-fortress/", "url": "https://exploredprk.com/history/pyongyang-fortress/", "quote": "Relying on its robust national power, Koguryo constructed a new capital fortified by walls surrounding the entire city. This new fortress was none other than Pyongyang Fortress.", "outcome": "found"}, {"source": "https://contents.history.go.kr/mobile/mid/kc_r101010", "url": "https://contents.history.go.kr/mobile/mid/kc_r101010", "quote": "산성과 평지성이 합쳐진 평산성(平山城) 구조로, 기존의 고구려 도성과는 달리 주민의 거주지역이 포함된 도시를 방어할 수 있도록 축조되었다는 점에서 획기적이라 할 수 있다.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0100)", "decision": "replace", "status": "CONFLICT", "reasoning": "Explore DPRK describes Pyongyang Castle as a fortress with walls enclosing the whole Goguryeo capital, and the National Institute of Korean History describes Jangan-seong (Pyongyang Castle) as a combined mountain-and-plain fortress (pyeongsanseong) built to defend the city; Wikidata also classes it as a fortress, so Fortress fits better than Castle/palace.", "value_page": null}]'::jsonb),
    ('c71054c1-6e0b-4e14-a8c8-83ffc79db502'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s009-rollback:c71054c1-6e0b-4e14-a8c8-83ffc79db502:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1 - 500 AD'' restored on T''akaq', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('c71054c1-6e0b-4e14-a8c8-83ffc79db502'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s009-rollback:c71054c1-6e0b-4e14-a8c8-83ffc79db502:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''1'' restored on T''akaq', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0114)", "decision": "clear", "status": "MISSING", "reasoning": "No source dates the archaeological site of T''akaq; the stored 1 AD comes from the mountain item and is unsupported, so the field is emptied.", "value_page": null}]'::jsonb),
    ('c71054c1-6e0b-4e14-a8c8-83ffc79db502'::uuid, 'site_type', NULL, 'City/town/settlement', 'fields-wd1-2026-09-26b-s009-rollback:c71054c1-6e0b-4e14-a8c8-83ffc79db502:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''City/town/settlement'' restored on T''akaq', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0114)", "decision": "clear", "status": "CONFLICT", "reasoning": "Sources only say there is an archaeological site of the same name on the mountain near Chavinillo; none says what kind of site it is, so City/town/settlement cannot be supported and the field is emptied.", "value_page": null}]'::jsonb),
    ('c75b6409-59b2-4675-a402-796d4b2ba6fb'::uuid, 'site_type', 'Dolmen', 'Megalithic structures', 'fields-wd1-2026-09-26b-s009-rollback:c75b6409-59b2-4675-a402-796d4b2ba6fb:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Megalithic structures'' restored on Kilclooney More', '[{"source": "https://www.discoverireland.ie/donegal/kilclooney-dolmen", "url": "https://www.discoverireland.ie/donegal/kilclooney-dolmen", "quote": "The Kilclooney Dolmen is an exceptionally fine portal-tome or dolmen, prominent on the skyline 6.5km north-north-west of Ardara in County Donegal.", "outcome": "found"}, {"source": "https://govisitdonegal.com/attractions/kilcooney-dolmen/", "url": "https://govisitdonegal.com/attractions/kilcooney-dolmen/", "quote": "Kilclooney Dolmen is one of the most remarkable prehistoric sites in Ireland.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0014)", "decision": "replace", "status": "CONFLICT", "reasoning": "Discover Ireland and Go Visit Donegal both describe the site as the Kilclooney Dolmen, a Neolithic portal tomb; ''Dolmen'' is the more specific canonical type than the stored ''Megalithic structures''.", "value_page": null}]'::jsonb),
    ('c75b6409-59b2-4675-a402-796d4b2ba6fb'::uuid, 'source_url', 'https://de.wikipedia.org/wiki/Kilclooney_More_1', 'https://en.wikipedia.org/wiki/Kilclooney_More', 'fields-wd1-2026-09-26b-s009-rollback:c75b6409-59b2-4675-a402-796d4b2ba6fb:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Kilclooney_More'' restored on Kilclooney More', '[{"source": "https://de.wikipedia.org/wiki/Kilclooney_More_1", "url": "https://de.wikipedia.org/wiki/Kilclooney_More_1", "quote": "Kilclooney More 1 oder Kilclooney More East ist ein Portal Tomb etwa 400 m östlich der Hauptstraße und 6,4 km nordnordwestlich von Ardara", "outcome": "found"}, {"source": "https://www.discoverireland.ie/donegal/kilclooney-dolmen", "url": "https://www.discoverireland.ie/donegal/kilclooney-dolmen", "quote": "The Kilclooney Dolmen is an exceptionally fine portal-tome or dolmen, prominent on the skyline 6.5km north-north-west of Ardara in County Donegal.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0082)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the townland of Kilclooney More; the dolmen''s own Wikipedia article is the German ''Kilclooney More 1'' (the portal tomb 6.4 km NNW of Ardara, Wikidata Q1741250), and Discover Ireland describes the same dolmen independently.", "value_page": {"lang": "de", "problem": null, "resolved_title": "Kilclooney More 1", "unreadable": false, "wikibase_item": "Q1741250"}}]'::jsonb),
    ('c76343df-e566-42b8-a0a8-5ce3060a46bd'::uuid, 'site_type', 'Sanctuary', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26b-s009-rollback:c76343df-e566-42b8-a0a8-5ce3060a46bd:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Necropolis/tombs complex'' restored on Nekromanteion of Acheron', '[{"source": "https://allofgreeceone.culture.gov.gr/en/venues/nekromanteion-of-acheron-preveza/", "url": "https://allofgreeceone.culture.gov.gr/en/venues/nekromanteion-of-acheron-preveza/", "quote": "The Nekromanteion of Acheron was excavated between 1958-1964 and 1976-1977. It was the first sanctuary and oracle of the Underworld gods to achieve fame.", "outcome": "found"}, {"source": "https://www.archaeology.wiki/blog/archaeological_site/the-nekromanteion-of-acheron/", "url": "https://www.archaeology.wiki/blog/archaeological_site/the-nekromanteion-of-acheron/", "quote": "In the main sanctuary of the Hellenistic Nekromanteion and on its ruins, the Convent of Hagios Ioannis or St John the Baptist of Likouresis was built, probably in the 16th century, also known as the Monastery of Thanesa.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Necromanteion_of_Acheron", "url": "https://en.wikipedia.org/wiki/Necromanteion_of_Acheron", "quote": "The Nekromanteion (Greek: Νεκρομαντεῖον) was an ancient Greek temple of necromancy devoted to Hades and Persephone.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0069)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Greek Ministry of Culture and archaeology.wiki describe the site as the sanctuary and oracle of the Underworld gods, and Wikipedia calls it a temple of necromancy; no source calls it a necropolis, so the stored tomb type is replaced by Sanctuary (a later reading as a fortified farmhouse is noted in Wikipedia but is not the site''s registered identity).", "value_page": null}]'::jsonb),
    ('c763d97d-a16f-41ae-b9e7-082ec0e0dcad'::uuid, 'geom', 'SRID=4326;POINT(-3.364305 40.481815)', '0101000020E6100000E001EE93F4EE0AC0F391D4BEBF3B4440', 'fields-wd1-2026-09-26b-s009-rollback:c763d97d-a16f-41ae-b9e7-082ec0e0dcad:geom', 'rollback of fields-wd1-2026-09-26b-s009: geom ''0101000020E6100000E001EE93F4EE0AC0F391D4BEBF3B4440'' restored on Alcalá de Henares', '[{"source": "https://www.wikidata.org/wiki/Q46940", "url": "https://www.wikidata.org/wiki/Q46940", "quote": "40°28''54.534\"N, 3°21''51.498\"W", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/209144042", "url": "https://www.openstreetmap.org/node/209144042", "quote": "40.4819540, -3.3639810", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0128)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored point is the rounded 40°28''N 3°22''W of the English article, 1.7 km south of the town across the Henares. Wikidata and the OpenStreetMap node of the city both put the centre of Alcala de Henares at 40.4818 N, 3.3643 W, within 35 m of each other.", "value_page": null}]'::jsonb),
