    ('c763d97d-a16f-41ae-b9e7-082ec0e0dcad'::uuid, 'lon', '-3.364305', '-3.366677432728679', 'fields-wd1-2026-09-26b-s009-rollback:c763d97d-a16f-41ae-b9e7-082ec0e0dcad:lon', 'rollback of fields-wd1-2026-09-26b-s009: lon ''-3.366677432728679'' restored on Alcalá de Henares', '[{"source": "https://www.wikidata.org/wiki/Q46940", "url": "https://www.wikidata.org/wiki/Q46940", "quote": "40°28''54.534\"N, 3°21''51.498\"W", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/209144042", "url": "https://www.openstreetmap.org/node/209144042", "quote": "40.4819540, -3.3639810", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0128)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored point is the rounded 40°28''N 3°22''W of the English article, 1.7 km south of the town across the Henares. Wikidata and the OpenStreetMap node of the city both put the centre of Alcala de Henares at 40.4818 N, 3.3643 W, within 35 m of each other.", "value_page": null}]'::jsonb),
    ('c778c6b2-749f-40eb-a1c6-1903c98b9660'::uuid, 'site_type', 'Fort', 'City/town/settlement', 'fields-wd1-2026-09-26b-s009-rollback:c778c6b2-749f-40eb-a1c6-1903c98b9660:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''City/town/settlement'' restored on Castro de Achadizo', '[{"source": "https://en.wikipedia.org/wiki/Castro_de_Achadizo", "url": "https://en.wikipedia.org/wiki/Castro_de_Achadizo", "quote": "Castro de Achadizo is an Iron Age fort hill", "outcome": "found"}, {"source": "https://www.galiciaturistica.es/patrimonio-cultural/i/85145584/castro-do-achadizo", "url": "https://www.galiciaturistica.es/patrimonio-cultural/i/85145584/castro-do-achadizo", "quote": "Este recinto fortificado data de la Edad del Hierro y forma parte del tipo de castros costeros, muy característicos de la región.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0129)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia calls the site an Iron Age hillfort (castro) and Galicia Turística a fortified enclosure of the coastal castro type; a walled castro is a hillfort, so Fort is more specific than the generic City/town/settlement.", "value_page": null}]'::jsonb),
    ('c7a242e3-1638-4260-82da-ec130f9cc023'::uuid, 'period_name', NULL, '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s009-rollback:c7a242e3-1638-4260-82da-ec130f9cc023:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''500 BC - 1 AD'' restored on Salamgarh', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('c7a242e3-1638-4260-82da-ec130f9cc023'::uuid, 'period_start', NULL, '-500', 'fields-wd1-2026-09-26b-s009-rollback:c7a242e3-1638-4260-82da-ec130f9cc023:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-500'' restored on Salamgarh', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0104)", "decision": "clear", "status": "MISSING", "reasoning": "The -500 rests on nothing: Wikipedia only reports a belief that Chandragupta Maurya built the fort c. 300 BC, the 1893 Gujrat District Gazetteer calls the Islamgarh mound ''very ancient'' without a date, and Humsub (after Ganesh Das) dates the fort itself to Rahmat Khan Waraich in 1758-59, a later conversion of the mound. No two independent sources securely date the start of the site, so the field is emptied.", "value_page": null}]'::jsonb),
    ('c7a242e3-1638-4260-82da-ec130f9cc023'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s009-rollback:c7a242e3-1638-4260-82da-ec130f9cc023:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Fortress/citadel'' restored on Salamgarh', '[{"source": "https://en.wikipedia.org/wiki/Salamgarh", "url": "https://en.wikipedia.org/wiki/Salamgarh", "quote": "There exist remnants of a fort believed to be built by Chandragupta Maurya in 300 BC. The original name of the village could not be ascertained but the fort became famous as Islamgarh Fort", "outcome": "found"}, {"source": "https://archive.org/download/in.ernet.dli.2015.35649/2015.35649.Gujrat-District-Gazetteer_djvu.txt", "url": "https://archive.org/download/in.ernet.dli.2015.35649/2015.35649.Gujrat-District-Gazetteer_djvu.txt", "quote": "in later times it was converted into a stronghold.", "outcome": "found"}, {"source": "https://humsub.com.pk/n/22313/2025/11/15/mansoor-behzad-butt/", "url": "https://humsub.com.pk/n/22313/2025/11/15/mansoor-behzad-butt/", "quote": "59 میں رحمت خان نے جلالپور جٹاں میں کلاچور قلعہ قائم کیا اور اسے اپنے والد کے نام پر اسلام گڑھ قلعہ کا نام دیا۔", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0104)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia describes the site by the remnants of Islamgarh Fort, the district gazetteer says the Islamgarh mound was later converted into a stronghold, and Humsub reports Rahmat Khan founding the fort and naming it Islamgarh fort; all describe a fort, so the specific type Fort replaces Fortress/citadel, a word none of them uses.", "value_page": null}]'::jsonb),
    ('c7a71867-0a74-4bf4-a77a-a0d53acbf2bb'::uuid, 'site_type', 'Monument', 'Megalithic structures', 'fields-wd1-2026-09-26b-s009-rollback:c7a71867-0a74-4bf4-a77a-a0d53acbf2bb:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Megalithic structures'' restored on Theban Treasury, Delphi', '[{"source": "https://delphi.culture.gr/archaelogical-site/monuments/", "url": "https://delphi.culture.gr/archaelogical-site/monuments/", "quote": "Monuments The Sicyonian Treasury The altar of the Chiots The Theban Treasury", "outcome": "found"}, {"source": "https://perseus-aa.github.io/items/aa_176.html", "url": "https://perseus-aa.github.io/items/aa_176.html", "quote": "Delphi, Treasury of the Thebans (VI) (Building) Temple-like building; in the southwestern corner of the Sanctuary of Apollo.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0073)", "decision": "replace", "status": "CONFLICT", "reasoning": "The treasury is a votive building dedicated by Thebes in the sanctuary of Apollo, not a megalithic structure: the Ministry of Culture''s Delphi site lists ''The Theban Treasury'' among the site''s Monuments, and Perseus describes it as a temple-like treasury building in the sanctuary; Monument is the canonical type that holds.", "value_page": null}]'::jsonb),
