    ('c7bbe836-c8b3-4e74-ae95-08724e63b389'::uuid, 'period_start', NULL, '-3000', 'fields-wd1-2026-09-26b-s009-rollback:c7bbe836-c8b3-4e74-ae95-08724e63b389:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-3000'' restored on Old Horom', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0005)", "decision": "clear", "status": "MISSING", "reasoning": "Excavations document habitation at Horom from the Early Bronze Age through the Urartian period (Armenia Discovery, Kiesling: ''Bronze Age through Urartian''), and Armenian-language sources date early finds to the (end of the) 3rd millennium BC while Armenian Geographic dates the fortress''s foundation to the 9th century BC; no two independent sources state a start date in a form that can be quoted, so the field is emptied.", "value_page": null}]'::jsonb),
    ('c7bbe836-c8b3-4e74-ae95-08724e63b389'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Horom_Citadel', 'https://en.wikipedia.org/wiki/Horom,_Armenia', 'fields-wd1-2026-09-26b-s009-rollback:c7bbe836-c8b3-4e74-ae95-08724e63b389:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Horom,_Armenia'' restored on Old Horom', '[{"source": "https://en.wikipedia.org/wiki/Horom_Citadel", "url": "https://en.wikipedia.org/wiki/Horom_Citadel", "quote": "Horom is considered to be one of the most impressive archaeological sites in Armenia because of its unique architecture.", "outcome": "found"}, {"source": "https://armeniadiscovery.com/en/place/horom-ancient-site-and-citadel", "url": "https://armeniadiscovery.com/en/place/horom-ancient-site-and-citadel", "quote": "The Horom fortress-settlement site is located in the Shirak plain, near the village of Horom.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0005)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about Horom village; English Wikipedia has a dedicated article on the archaeological site, Horom Citadel, which Armenia Discovery independently describes.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Horom Citadel", "unreadable": false, "wikibase_item": "Q5904838"}}]'::jsonb),
    ('c80bf1e4-215a-440d-9e2e-848c40348037'::uuid, 'site_type', 'Cave', 'Archaeological site', 'fields-wd1-2026-09-26b-s009-rollback:c80bf1e4-215a-440d-9e2e-848c40348037:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Archaeological site'' restored on Krapina Neanderthal Site', '[{"source": "https://en.wikipedia.org/wiki/Krapina_Neanderthal_site", "url": "https://en.wikipedia.org/wiki/Krapina_Neanderthal_site", "quote": "The prehistoric site itself is located in a collapsed cave", "outcome": "found"}, {"source": "https://ice-age-europe.eu/visit-us/krapina-neanderthal-museum.html", "url": "https://ice-age-europe.eu/visit-us/krapina-neanderthal-museum.html", "quote": "discover the remains of the cave that once was a home to the Krapina Neanderthals", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0018)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Ice Age Europe network page both describe the Hušnjakovo Neanderthal site as a (collapsed) cave that the Krapina Neanderthals inhabited; Cave is more specific than the generic Archaeological site.", "value_page": null}]'::jsonb),
