    ('c858e9e8-6b70-45b6-9771-9f1e20c6dfa3'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s009-rollback:c858e9e8-6b70-45b6-9771-9f1e20c6dfa3:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Fortress/citadel'' restored on Allt yr Esgair', '[{"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=1780", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=1780", "quote": "This site comprises a large, multivallate fort, measuring 700m NW/SE by 114m, which occupies the summit of an elongated ridge on the eastern side of the Usk river valley.", "outcome": "found"}, {"source": "https://coflein.gov.uk/en/sites/92158", "url": "https://coflein.gov.uk/en/sites/92158", "quote": "A very large, multivallate fort occupies the upper part of a prominent ridge rising to 393 m above O.D. between the Usk and Afon Llynfi, 3 km N.W. of Bwlch.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0152)", "decision": "replace", "status": "CONFLICT", "reasoning": "Cadw''s scheduling record and the RCAHMW inventory text on Coflein both describe the site as a large multivallate (hill)fort, which is a fort rather than a fortress or citadel.", "value_page": null}]'::jsonb),
