    ('c8d2c13e-fd9a-466c-9fdc-fc26ee798ded'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s009-rollback:c8d2c13e-fd9a-466c-9fdc-fc26ee798ded:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''1'' restored on Baltic Sea Anomaly', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0010)", "decision": "clear", "status": "MISSING", "reasoning": "The anomaly is not a built or occupied site: Wikipedia reports an expert consensus that it is a natural geological formation, and the geologist who studied the samples says it formed through glacial and postglacial processes. No source gives a year, century or millennium for its start, and the stored 1 AD has no basis, so the field is emptied.", "value_page": null}]'::jsonb),
    ('c8d2c13e-fd9a-466c-9fdc-fc26ee798ded'::uuid, 'site_type', 'Natural feature', 'Underwater structures', 'fields-wd1-2026-09-26b-s009-rollback:c8d2c13e-fd9a-466c-9fdc-fc26ee798ded:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Underwater structures'' restored on Baltic Sea Anomaly', '[{"source": "https://en.wikipedia.org/wiki/Baltic_Sea_anomaly", "url": "https://en.wikipedia.org/wiki/Baltic_Sea_anomaly", "quote": "A consensus of experts and scientists say that the image most likely shows a natural geological formation.", "outcome": "found"}, {"source": "https://www.livescience.com/22846-mysterious-baltic-sea-object-is-a-glacial-deposit.html", "url": "https://www.livescience.com/22846-mysterious-baltic-sea-object-is-a-glacial-deposit.html", "quote": "Because the whole northern Baltic region is so heavily influenced by glacial thawing processes, both the feature and the rock samples are likely to have formed in connection with glacial and postglacial processes,", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0010)", "decision": "replace", "status": "CONFIRMED", "reasoning": "Wikipedia reports an expert consensus that the sonar image shows a natural geological formation, and Live Science quotes the Stockholm University geologist who analysed the samples saying the feature formed through glacial and postglacial processes. Nothing built is attested, so ''Underwater structures'' is wrong and ''Natural feature'' fits.", "value_page": null}]'::jsonb),
    ('c8dc3d03-6c81-4ef7-a8f2-e2cb2d047359'::uuid, 'period_name', '3000 - 1500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s009-rollback:c8dc3d03-6c81-4ef7-a8f2-e2cb2d047359:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''4500 - 3000 BC'' restored on Fournou Korifi', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-2600) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('c8dc3d03-6c81-4ef7-a8f2-e2cb2d047359'::uuid, 'period_start', '-2600', '-4500', 'fields-wd1-2026-09-26b-s009-rollback:c8dc3d03-6c81-4ef7-a8f2-e2cb2d047359:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-4500'' restored on Fournou Korifi', '[{"source": "https://topostext.org/place/350256XFou", "url": "https://topostext.org/place/350256XFou", "quote": "An Early Minoan coastal settlement (2600-2300 BC) near Hierapetra", "outcome": "found"}, {"source": "http://ierapetra.gr/index.php/el/history-culture/minoan-ancient-roman-period/74-fournou-koryfi", "url": "http://ierapetra.gr/index.php/el/history-culture/minoan-ancient-roman-period/74-fournou-koryfi", "quote": "Ο οικισμός στη Φούρνου Κορυφή ιδρύθηκε και καταστράφηκε από φωτιά στην Πρωτομινωική II περίοδο (2600-2300 π.Χ.).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0064)", "decision": "replace", "status": "MISSING", "reasoning": "ToposText and the Municipality of Ierapetra both say the settlement was founded in Early Minoan II, 2600-2300 BC; the start, 2600 BC, lies in 3000 - 1500 BC, not in the stored 4500 - 3000 BC bucket.", "value_page": null}]'::jsonb),
    ('c8dc3d03-6c81-4ef7-a8f2-e2cb2d047359'::uuid, 'site_type', 'Settlement', 'City/town/settlement', 'fields-wd1-2026-09-26b-s009-rollback:c8dc3d03-6c81-4ef7-a8f2-e2cb2d047359:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''City/town/settlement'' restored on Fournou Korifi', '[{"source": "https://topostext.org/place/350256XFou", "url": "https://topostext.org/place/350256XFou", "quote": "Fournou Kefala, Minoan settlement excavated on Fournou Kefala hill just W of Nea Myrtos, Lasithi Crete", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Fournou_Korifi", "url": "https://en.wikipedia.org/wiki/Fournou_Korifi", "quote": "Fournou Korifi is the archaeological site of a Minoan settlement on southern", "outcome": "found"}, {"source": "http://www.minoancrete.com/fournou.htm", "url": "http://www.minoancrete.com/fournou.htm", "quote": "A unique EMII settlement", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0064)", "decision": "replace", "status": "MISSING", "reasoning": "ToposText, English Wikipedia and Minoan Crete all describe a small Early Minoan hilltop settlement of about 100 rooms, not a city or town, so the specific type Settlement replaces the composite City/town/settlement.", "value_page": null}]'::jsonb),
