    ('c9ea41a4-53e0-481a-9e3c-d314cfa36c9e'::uuid, 'site_type', 'Settlement', 'City/town/settlement', 'fields-wd1-2026-09-26b-s009-rollback:c9ea41a4-53e0-481a-9e3c-d314cfa36c9e:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''City/town/settlement'' restored on Castro of Santa Trega', '[{"source": "https://en.wikipedia.org/wiki/Castro_of_Santa_Trega", "url": "https://en.wikipedia.org/wiki/Castro_of_Santa_Trega", "quote": "Santa Trega is a ''Castro-Roman'' settlement. It was inhabited between 100 BC and 100 AD", "outcome": "found"}, {"source": "https://www.castillosnet.org/monumento.php?r=PO-CAS-020&seo=castro-celta-de-santa-tecla", "url": "https://www.castillosnet.org/monumento.php?r=PO-CAS-020&seo=castro-celta-de-santa-tecla", "quote": "Este poblado está situado a 341 metros de altura, llegó a tener unos 5.000 habitantes en su época de mayor esplendor", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0130)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia calls Santa Trega a Castro-Roman settlement and CastillosNet a walled ''poblado'' (settlement) of up to 5,000 inhabitants; it is an Iron Age hillfort settlement, so the specific type is Settlement rather than City/town/settlement.", "value_page": null}]'::jsonb),
    ('ca012875-d72b-4d00-99a7-0246f1769a32'::uuid, 'site_type', 'Settlement', 'Church/cathedral', 'fields-wd1-2026-09-26b-s009-rollback:ca012875-d72b-4d00-99a7-0246f1769a32:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Church/cathedral'' restored on Golem Grad', '[{"source": "https://www.fastionline.org/site/AIAC_671", "url": "https://www.fastionline.org/site/AIAC_671", "quote": "The site represents settlement from the Neolithic period and Hellenistic and Roman times.", "outcome": "found"}, {"source": "https://history.mk/the-story-of-the-mysterious-island-of-golem-grad-in-lake-prespa/", "url": "https://history.mk/the-story-of-the-mysterious-island-of-golem-grad-in-lake-prespa/", "quote": "More intense traces of life in the settlement were discovered and dated to the 4th century BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0100)", "decision": "replace", "status": "CONFLICT", "reasoning": "Golem Grad is an island-wide multi-period settlement (Hellenistic and Roman houses, a cistern, cemeteries) whose churches are only one of its phases; Fasti and history.mk both describe it as a settlement, not as a church.", "value_page": null}]'::jsonb),
