    ('cab41f26-0bf2-4078-a0c9-6e173fcdc837'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Bar%27an_Temple', 'https://en.wikipedia.org/wiki/Barran_Temple', 'fields-wd1-2026-09-26b-s009-rollback:cab41f26-0bf2-4078-a0c9-6e173fcdc837:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Barran_Temple'' restored on Throne of Queen Sheba - Barran Temple', '[{"source": "https://en.wikipedia.org/wiki/Bar%27an_Temple", "url": "https://en.wikipedia.org/wiki/Bar%27an_Temple", "quote": "Barran Temple in Marib governorate, 2017.", "outcome": "found"}, {"source": "https://ancientarabia.huma-num.fr/gazetteer/places/52", "url": "https://ancientarabia.huma-num.fr/gazetteer/places/52", "quote": "The Barʾan temple (brʾn in the Ancient South Arabian inscriptions) is an extra-muros religious complex located at al-ʿAmāyid, in the southern oasis of Maʾrib.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0156)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Barran_Temple URL is only a redirect; the article itself is Bar''an_Temple, about this Sabaean temple near Marib, and the CNR-CNRS gazetteer entry names the same temple as the Barʾan temple, al-ʿAmāyid (Arsh Bilqis).", "value_page": {"lang": "en", "problem": null, "resolved_title": "Bar''an Temple", "unreadable": false, "wikibase_item": "Q16120623"}}]'::jsonb),
    ('cac95409-52f9-4a26-bf59-fd7af98d054e'::uuid, 'site_type', 'Religious', 'Temple complex', 'fields-wd1-2026-09-26b-s009-rollback:cac95409-52f9-4a26-bf59-fd7af98d054e:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Temple complex'' restored on Anim Synagogue', '[{"source": "https://en.wikipedia.org/wiki/Horvat_%27Anim", "url": "https://en.wikipedia.org/wiki/Horvat_%27Anim", "quote": "Archaeological remains of a rectangular, basilical synagogue (approx. 14.5 × 8.5 m) date its main phase to the 4th–7th centuries CE", "outcome": "found"}, {"source": "https://moses.creighton.edu/vr/Anim/txt/intro.html", "url": "https://moses.creighton.edu/vr/Anim/txt/intro.html", "quote": "The ark would have been located on a large bema at the northern end of the prayer hall.", "outcome": "found"}, {"source": "https://archaeolist.com/sites/israel/anim-synagogue", "url": "https://archaeolist.com/sites/israel/anim-synagogue", "quote": "The synagogue served the Jewish community until the 7th century CE when it was converted into a mosque, illustrating the dynamic religious changes in the region.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0014)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia, the Creighton University Moses project and Archaeolist all describe the Anim Synagogue as a single ancient Jewish house of worship (a basilical synagogue with a prayer hall and Torah-ark bema, in use in the 4th-7th centuries CE), not a temple complex; no canonical type names a synagogue, so the generic Religious type is the most specific that fits.", "value_page": null}]'::jsonb),
    ('cae9d762-cdd4-4833-adc3-c426b7a79948'::uuid, 'period_name', '500 BC - 1 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s009-rollback:cae9d762-cdd4-4833-adc3-c426b7a79948:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1 - 500 AD'' restored on Aynuna', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-100) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('cae9d762-cdd4-4833-adc3-c426b7a79948'::uuid, 'period_start', '-100', '1', 'fields-wd1-2026-09-26b-s009-rollback:cae9d762-cdd4-4833-adc3-c426b7a79948:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''1'' restored on Aynuna', '[{"source": "https://pam-journal.pl/en/issues/29-vol-29-issue-1-special-issue/aynuna-on-the-red-sea", "url": "https://pam-journal.pl/en/issues/29-vol-29-issue-1-special-issue/aynuna-on-the-red-sea", "quote": "It is a Nabataean port dated to the 1st century BC, with later occupation in the 4th century AD and with some Islamic presence.", "outcome": "found"}, {"source": "https://books.openedition.org/momeditions/16356", "url": "https://books.openedition.org/momeditions/16356", "quote": "This paper presents the evidence for a Nabataean presence in the 1st century BC and the 1st century AD, such as coins, an inscription and an aqueduct.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0121)", "decision": "replace", "status": "MISSING", "reasoning": "The excavators'' reports in Polish Archaeology in the Mediterranean and in a MOM Éditions volume date the Nabataean port at Aynuna to the 1st century BC. The start is therefore -100, in the 500 BC - 1 AD bucket, not the stored 1 - 500 AD.", "value_page": null}]'::jsonb),
    ('cafcb3e7-fc61-4867-98ba-0a5f3cf68d6e'::uuid, 'period_name', '4500 - 3000 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s009-rollback:cafcb3e7-fc61-4867-98ba-0a5f3cf68d6e:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''3000 - 1500 BC'' restored on Abu Salabikh', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3900) = ''4500 - 3000 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('cafcb3e7-fc61-4867-98ba-0a5f3cf68d6e'::uuid, 'period_start', '-3900', '-3000', 'fields-wd1-2026-09-26b-s009-rollback:cafcb3e7-fc61-4867-98ba-0a5f3cf68d6e:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-3000'' restored on Abu Salabikh', '[{"source": "https://www.historyfiles.co.uk/KingListsMiddEast/MesopotamiaAbuSalabikh.htm", "url": "https://www.historyfiles.co.uk/KingListsMiddEast/MesopotamiaAbuSalabikh.htm", "quote": "True settlement and building only appears to have began with the onset of the Uruk IV period around 3900 BC.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Abu_Salabikh", "url": "https://en.wikipedia.org/wiki/Abu_Salabikh", "quote": "Two grain samples from the Middle Uruk layer of the Uruk Mound were accelerator radiocarbon dated with calibrated dates of 3520 ± 130 BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0079)", "decision": "replace", "status": "CONFLICT", "reasoning": "The History Files dates the start of true settlement at Abu Salabikh to around 3900 BC, and Wikipedia''s radiocarbon dates put the Uruk Mound''s Middle Uruk layer (above the Early Uruk occupation) at 3520 ± 130 BC; earlier Neolithic traces are only light and undated. The attested start therefore lies in 4500 - 3000 BC, not in the stored 3000 - 1500 BC bucket.", "value_page": null}]'::jsonb),
    ('cb2858ad-2ca7-4d48-9d71-0e3ced3a2d31'::uuid, 'period_name', '500 BC - 1 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s009-rollback:cb2858ad-2ca7-4d48-9d71-0e3ced3a2d31:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1500 - 500 BC'' restored on Stoa of the Athenians', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-478) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('cb2858ad-2ca7-4d48-9d71-0e3ced3a2d31'::uuid, 'period_start', '-478', '-1500', 'fields-wd1-2026-09-26b-s009-rollback:cb2858ad-2ca7-4d48-9d71-0e3ced3a2d31:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-1500'' restored on Stoa of the Athenians', '[{"source": "https://en.wikipedia.org/wiki/Stoa_of_the_Athenians", "url": "https://en.wikipedia.org/wiki/Stoa_of_the_Athenians", "quote": "The stoa was constructed in Delphi after the naval victory over the Persians at Sestus near the Hellespont in 478 BC.", "outcome": "found"}, {"source": "https://www.greeka.com/sterea/delphi/sightseeing/athenian-stoa/", "url": "https://www.greeka.com/sterea/delphi/sightseeing/athenian-stoa/", "quote": "This remarkable work dates back to 478 B.C and it was built according to the Ionic style to host the trophies of the Athenians from their sea battles against the Persians.", "outcome": "found"}, {"source": "https://www.exploring-greece.gr/en/show/38045/:ttd/STOA-ATHINEON", "url": "https://www.exploring-greece.gr/en/show/38045/:ttd/STOA-ATHINEON", "quote": "The Stoa is dated to after 478 BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0072)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia, Greeka and Exploring Greece date the stoa''s construction to 478 BC or just after (after the victory at Sestos); that lies in the bucket 500 BC - 1 AD, not in the stored 1500 - 500 BC, so the value is replaced with -478.", "value_page": null}]'::jsonb),
    ('cb2858ad-2ca7-4d48-9d71-0e3ced3a2d31'::uuid, 'site_type', 'Monument', 'Polygonal masonry', 'fields-wd1-2026-09-26b-s009-rollback:cb2858ad-2ca7-4d48-9d71-0e3ced3a2d31:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Polygonal masonry'' restored on Stoa of the Athenians', '[{"source": "https://en.wikipedia.org/wiki/Stoa_of_the_Athenians", "url": "https://en.wikipedia.org/wiki/Stoa_of_the_Athenians", "quote": "The monument has been identified through the inscription of the stylobate", "outcome": "found"}, {"source": "https://thedelphiguide.com/the-stoa-of-the-athenians/", "url": "https://thedelphiguide.com/the-stoa-of-the-athenians/", "quote": "The monument has been identified through the inscription of attic letters on the stylobate", "outcome": "found"}, {"source": "https://www.greeka.com/sterea/delphi/sightseeing/athenian-stoa/", "url": "https://www.greeka.com/sterea/delphi/sightseeing/athenian-stoa/", "quote": "Among the most important offerings of the Athenians in the site of Delphi is the known Stoa located at the center of Apollo sanctuary.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0072)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is an Ionic stoa (portico) dedicated by the Athenians in the Sanctuary of Apollo at Delphi, which Wikipedia and The Delphi Guide call a monument; it only leans against the older Polygonal Wall, so ''Polygonal masonry'' describes its neighbour, not the stoa, and no canonical type names a stoa.", "value_page": null}]'::jsonb),
    ('cb637b1a-4f1b-4856-815f-67f2424a717f'::uuid, 'period_name', '1000 - 1500 AD', '500 - 1000 AD', 'fields-wd1-2026-09-26b-s009-rollback:cb637b1a-4f1b-4856-815f-67f2424a717f:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''500 - 1000 AD'' restored on Fa''ahia', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1050) = ''1000 - 1500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('cb637b1a-4f1b-4856-815f-67f2424a717f'::uuid, 'period_start', '1050', '500', 'fields-wd1-2026-09-26b-s009-rollback:cb637b1a-4f1b-4856-815f-67f2424a717f:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''500'' restored on Fa''ahia', '[{"source": "https://pacificarchaeology.org/index.php/journal/article/view/279", "url": "https://pacificarchaeology.org/index.php/journal/article/view/279", "quote": "Renewed excavations in the Fa''hia site area in 2007, although relatively limited in scope produced more stratigraphic detail, additional faunal remains and artefacts, including a patu, and 12 new radiocarbon dates on short lifespan material from the lowest cultural layer which indicate initial human occupation about AD 1050-1160.", "outcome": "found"}, {"source": "https://researchportalplus.anu.edu.au/en/publications/new-radiocarbon-ages-of-colonization-sites-in-east-polynesia/", "url": "https://researchportalplus.anu.edu.au/en/publications/new-radiocarbon-ages-of-colonization-sites-in-east-polynesia/", "quote": "Leaving aside questionable results on bone and wood samples, six shell samples from Vaito''otia-Fa''ahia indicate occupation in the period A.D. 1050-1450.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0052)", "decision": "replace", "status": "MISSING", "reasoning": "The re-dating of the site on short-lived material (Anderson et al. 2019, Journal of Pacific Archaeology) puts initial occupation at about AD 1050-1160, and the earlier shell re-dating (Anderson & Sinoto 2002, Asian Perspectives) at AD 1050-1450; the older AD 700/850 starts rest on samples with inbuilt age, so the attested start is c. AD 1050, in the 1000 - 1500 AD bucket.", "value_page": null}]'::jsonb),
    ('cb637b1a-4f1b-4856-815f-67f2424a717f'::uuid, 'site_type', 'Settlement', 'City/town/settlement', 'fields-wd1-2026-09-26b-s009-rollback:cb637b1a-4f1b-4856-815f-67f2424a717f:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''City/town/settlement'' restored on Fa''ahia', '[{"source": "https://pacificarchaeology.org/index.php/journal/article/view/279", "url": "https://pacificarchaeology.org/index.php/journal/article/view/279", "quote": "The six-hectare site of Vaito''otia-Fa''ahia on Huahine Island in the Leeward Societies is renowned for its wealth of material culture typifying early East Polynesian settlement", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Fa%CA%BBahia", "url": "https://en.wikipedia.org/wiki/Fa%CA%BBahia", "quote": "Faʻahia is an early Polynesian occupation site in the north-east of the island of Huahine, in the Society Islands, French Polynesia.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0052)", "decision": "replace", "status": "MISSING", "reasoning": "Fa''ahia is a six-hectare early Polynesian occupation (habitation) site of the colonisation period, not a town or city; the specific canonical type for such a site is Settlement.", "value_page": null}]'::jsonb),
    ('cb637b1a-4f1b-4856-815f-67f2424a717f'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Fa%CA%BBahia', 'https://en.wikipedia.org/wiki/Fa%27ahia', 'fields-wd1-2026-09-26b-s009-rollback:cb637b1a-4f1b-4856-815f-67f2424a717f:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Fa%27ahia'' restored on Fa''ahia', '[{"source": "https://en.wikipedia.org/wiki/Fa%CA%BBahia", "url": "https://en.wikipedia.org/wiki/Fa%CA%BBahia", "quote": "Faʻahia is an early Polynesian occupation site in the north-east of the island of Huahine, in the Society Islands, French Polynesia.", "outcome": "found"}, {"source": "https://www.persee.fr/doc/jso_0300-953x_1984_num_40_79_2546", "url": "https://www.persee.fr/doc/jso_0300-953x_1984_num_40_79_2546", "quote": "The land immediately to the north is known as Fa''ahia, and the archaeological deposits are now known to extend into this land division too.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0052)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is a redirect to the English Wikipedia article ''Faʻahia'', which is about this very site; the article''s own URL replaces the redirect.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Faʻahia", "unreadable": false, "wikibase_item": "Q239890"}}]'::jsonb),
    ('cb8cc790-ac27-4f13-afb0-b12a3cf4e6db'::uuid, 'source_url', 'https://it.wikipedia.org/wiki/Pallanum', 'https://en.wikipedia.org/wiki/Pallanum', 'fields-wd1-2026-09-26b-s009-rollback:cb8cc790-ac27-4f13-afb0-b12a3cf4e6db:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Pallanum'' restored on Pallanum - Mura Megalitiche (Paladine) di Pallanum', '[{"source": "https://it.wikipedia.org/wiki/Pallanum", "url": "https://it.wikipedia.org/wiki/Pallanum", "quote": "Pallanum era un''antica città del popolo italico dei Lucanati, oggi sito archeologico sul Monte Pallano.", "outcome": "found"}, {"source": "https://www.gditaly.com/italy/abruzzo/ruins/pallanum.htm", "url": "https://www.gditaly.com/italy/abruzzo/ruins/pallanum.htm", "quote": "Pallanum (archaeological site) - ITALY (Sito Archeologico Pallanum - Abruzzo)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0087)", "decision": "replace", "status": "CONFLICT", "reasoning": "There is no English Wikipedia article ''Pallanum''; the Italian Wikipedia article Pallanum is about this archaeological site on Monte Pallano, which GDItaly also describes.", "value_page": {"lang": "it", "problem": null, "resolved_title": "Pallanum", "unreadable": false, "wikibase_item": "Q3892331"}}]'::jsonb),
    ('cc3e0e34-8532-41dd-9988-6c20e37be8e6'::uuid, 'period_name', NULL, '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s009-rollback:cc3e0e34-8532-41dd-9988-6c20e37be8e6:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''500 BC - 1 AD'' restored on Rocha da Mina', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('cc3e0e34-8532-41dd-9988-6c20e37be8e6'::uuid, 'period_start', NULL, '-500', 'fields-wd1-2026-09-26b-s009-rollback:cc3e0e34-8532-41dd-9988-6c20e37be8e6:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-500'' restored on Rocha da Mina', '[{"source": "WD1 decision (counted, round 1, wd1-r1-b0021)", "decision": "clear", "status": "MISSING", "reasoning": "The readable sources on Rocha da Mina (Terena, Alandroal, Evora) do not agree on when the site begins: the excavators'' listing on the Archaeological Institute of America fieldwork bulletin says the first occupants arrived in the 50s BCE, the national archaeology portal gives only the period label ''Idade do Ferro - 2º e Romano, República'' with no year, and the Megalithic Portal and A Magazine speak of occupation from the 1st and 2nd Iron Age. The project''s own website that carries the 1st century BCE date is refused to the quote checker (403), so no two independent readable sources date the start and the field is cleared.", "value_page": null}]'::jsonb),
    ('cc3e0e34-8532-41dd-9988-6c20e37be8e6'::uuid, 'site_type', 'Sanctuary', 'Megalithic structures', 'fields-wd1-2026-09-26b-s009-rollback:cc3e0e34-8532-41dd-9988-6c20e37be8e6:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Megalithic structures'' restored on Rocha da Mina', '[{"source": "https://en.wikipedia.org/wiki/Endovelicus", "url": "https://en.wikipedia.org/wiki/Endovelicus", "quote": "there is the Santuário da Rocha da Mina (Mina''s Rock Sanctuary); some authors classify it as a temple of Endovelicus.", "outcome": "found"}, {"source": "https://arqueologia.patrimoniocultural.pt/index.php?sid=sitios&subsid=53518", "url": "https://arqueologia.patrimoniocultural.pt/index.php?sid=sitios&subsid=53518", "quote": "Santuário rupestre implantado num esporão rochoso com vertentes abruptas, cuja área habitável é extremamente reduzida.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0118)", "decision": "replace", "status": "MISSING", "reasoning": "The Portuguese heritage agency''s register (type Santuário) and English Wikipedia describe Rocha da Mina as a rock-cut sanctuary, possibly of Endovelicus, with carved steps and pavements; it is not a megalithic structure.", "value_page": null}]'::jsonb),
    ('cc3e0e34-8532-41dd-9988-6c20e37be8e6'::uuid, 'source_url', 'https://arqueologia.patrimoniocultural.pt/index.php?sid=sitios&subsid=53518', 'www.megalithic.co.uk/article.php?sid=37238', 'fields-wd1-2026-09-26b-s009-rollback:cc3e0e34-8532-41dd-9988-6c20e37be8e6:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''www.megalithic.co.uk/article.php?sid=37238'' restored on Rocha da Mina', '[{"source": "https://arqueologia.patrimoniocultural.pt/index.php?sid=sitios&subsid=53518", "url": "https://arqueologia.patrimoniocultural.pt/index.php?sid=sitios&subsid=53518", "quote": "Rocha da Mina Sítio (10539)", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=37238", "url": "https://www.megalithic.co.uk/article.php?sid=37238", "quote": "Site Name: Rocha da Mina Alternative Name: Santuário a Endovélico da Rocha da Mina", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0118)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored value lacks a scheme and the site has no Wikipedia article of its own, so the heritage register entry of the Portal do Arqueólogo (CNS 10539) for Rocha da Mina is used; the Megalithic Portal names the same site.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('cc4c3c3a-1ada-47d8-93ea-2cbb7930f772'::uuid, 'period_name', '3000 - 1500 BC', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s009-rollback:cc4c3c3a-1ada-47d8-93ea-2cbb7930f772:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1500 - 500 BC'' restored on Castle Hill, Huddersfield', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-2000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('cc4c3c3a-1ada-47d8-93ea-2cbb7930f772'::uuid, 'period_start', '-2000', '-1500', 'fields-wd1-2026-09-26b-s009-rollback:cc4c3c3a-1ada-47d8-93ea-2cbb7930f772:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-1500'' restored on Castle Hill, Huddersfield', '[{"source": "https://www.mylearning.org/stories/who-were-the-first-people-to-live-in-kirklees/castle-hill", "url": "https://www.mylearning.org/stories/who-were-the-first-people-to-live-in-kirklees/castle-hill", "quote": "Scientific evidence shows this community lived here around 2000 BCE.", "outcome": "found"}, {"source": "https://kirkleescousins.co.uk/castle-hill-the-history-of-an-iron-age-hill-fort/", "url": "https://kirkleescousins.co.uk/castle-hill-the-history-of-an-iron-age-hill-fort/", "quote": "In the early Bronze Age around 2500 to 1500 BC, settlement on the hill would have been in organised communities of round houses.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0030)", "decision": "replace", "status": "MISSING", "reasoning": "The first attested occupation of the hilltop is Bronze Age settlement dated by scientific evidence to around 2000 BCE (MyLearning), placed in the early Bronze Age 2500-1500 BC by Kirklees Cousins; Wikipedia and Kirklees Council likewise say the hill has been settled for over 4,000 years. This falls in the 3000 - 1500 BC bucket, before the hillfort (c. 590/555 BC), so the stored -1500 is replaced.", "value_page": null}]'::jsonb),
    ('cc4c3c3a-1ada-47d8-93ea-2cbb7930f772'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s009-rollback:cc4c3c3a-1ada-47d8-93ea-2cbb7930f772:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Fortress/citadel'' restored on Castle Hill, Huddersfield', '[{"source": "https://www.kirklees.gov.uk/castlehill", "url": "https://www.kirklees.gov.uk/castlehill", "quote": "The site was developed as an iron age hill fort, surrounded by defensive ditches and ramparts.", "outcome": "found"}, {"source": "https://www.roman-britain.co.uk/places/castle-hill-almondbury/", "url": "https://www.roman-britain.co.uk/places/castle-hill-almondbury/", "quote": "Around 590 BC, an univallate fort was built in approximately the same 5 acres of land as the previous enclosure", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0030)", "decision": "replace", "status": "CONFLICT", "reasoning": "Kirklees Council and Roman-Britain.co.uk describe the monument as an Iron Age hill fort (later overlain by a motte-and-bailey castle); Fort is the most specific canonical type for the hillfort, rather than Fortress/citadel.", "value_page": null}]'::jsonb),
    ('cc5d001f-1ebf-44b8-a478-bfb78ec2d8d8'::uuid, 'period_name', '1500 - 500 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s009-rollback:cc5d001f-1ebf-44b8-a478-bfb78ec2d8d8:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''3000 - 1500 BC'' restored on Kalapodi', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1400) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('cc5d001f-1ebf-44b8-a478-bfb78ec2d8d8'::uuid, 'period_start', '-1400', '-2000', 'fields-wd1-2026-09-26b-s009-rollback:cc5d001f-1ebf-44b8-a478-bfb78ec2d8d8:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-2000'' restored on Kalapodi', '[{"source": "https://de.wikipedia.org/wiki/Kalapodi", "url": "https://de.wikipedia.org/wiki/Kalapodi", "quote": "Dabei liegt der Schwerpunkt auf dem südlichen Tempel und seinen Vorgängerbauten, die nach neuesten Erkenntnissen mindestens bis in das 14. Jahrhundert v. Chr., wenn nicht sogar in die mittelhelladische Zeit zurückreichen.", "outcome": "found"}, {"source": "https://www.helladic.info/MAPC/pkey_report_wparam.php?place=C1627", "url": "https://www.helladic.info/MAPC/pkey_report_wparam.php?place=C1627", "quote": "7. LH IIIA1: (1410 BC - 1375 BC) a. Kramer-Hajos [2016]: 9, ''The sanctuary of Kalapodi was continuously in use from at least LHIIIA1 ...''", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0066)", "decision": "replace", "status": "MISSING", "reasoning": "The sanctuary''s securely attested use begins with the first temple in Late Helladic IIIA1, the 14th century BC; a Middle Helladic start is only possible, so the start is c. 1400 BC rather than the stored 2000 BC.", "value_page": null}]'::jsonb),
    ('cc5d001f-1ebf-44b8-a478-bfb78ec2d8d8'::uuid, 'site_type', 'Sanctuary', 'Temple', 'fields-wd1-2026-09-26b-s009-rollback:cc5d001f-1ebf-44b8-a478-bfb78ec2d8d8:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Temple'' restored on Kalapodi', '[{"source": "https://www.dainst.org/en/research/projects/kalapodi-ein-phokisches-heiligtum-mit-langer-tradition/5990", "url": "https://www.dainst.org/en/research/projects/kalapodi-ein-phokisches-heiligtum-mit-langer-tradition/5990", "quote": "In the shadow of Mount Parnassus, near Kalapodi, lies an ancient sanctuary, likely the venerable Oracle of Apollo at Abae.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Kalapodi", "url": "https://en.wikipedia.org/wiki/Kalapodi", "quote": "The name Kalapodi also denotes an archaeological site ca. 1 km east of the village, where an ancient sanctuary was discovered.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0066)", "decision": "replace", "status": "CONFLICT", "reasoning": "The excavators (DAI) and Wikipedia describe the site as a sanctuary holding two parallel temple sequences and an enclosure wall; Sanctuary covers the whole site, where Temple names only part of it.", "value_page": null}]'::jsonb),
    ('cc5d001f-1ebf-44b8-a478-bfb78ec2d8d8'::uuid, 'source_url', 'https://www.dainst.org/en/research/projects/kalapodi-ein-phokisches-heiligtum-mit-langer-tradition/5990', 'https://en.wikipedia.org/wiki/Kalapodi', 'fields-wd1-2026-09-26b-s009-rollback:cc5d001f-1ebf-44b8-a478-bfb78ec2d8d8:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Kalapodi'' restored on Kalapodi', '[{"source": "https://www.dainst.org/en/research/projects/kalapodi-ein-phokisches-heiligtum-mit-langer-tradition/5990", "url": "https://www.dainst.org/en/research/projects/kalapodi-ein-phokisches-heiligtum-mit-langer-tradition/5990", "quote": "Kalapodi. A Phocian Sanctuary with a Long Tradition", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Kalapodi", "url": "https://en.wikipedia.org/wiki/Kalapodi", "quote": "The name Kalapodi also denotes an archaeological site ca. 1 km east of the village, where an ancient sanctuary was discovered.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0066)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the modern village; the German Archaeological Institute''s project page is about the Kalapodi sanctuary itself, which the Institute excavates.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('cc5d8fbd-741d-4da3-9ac4-c7bd797d4fd8'::uuid, 'geom', 'SRID=4326;POINT(15.86624 38.39415)', '0101000020E6100000E83915CB31B32F400E064672F42E4340', 'fields-wd1-2026-09-26b-s009-rollback:cc5d8fbd-741d-4da3-9ac4-c7bd797d4fd8:geom', 'rollback of fields-wd1-2026-09-26b-s009: geom ''0101000020E6100000E83915CB31B32F400E064672F42E4340'' restored on Tauriana', '[{"source": "https://it.wikipedia.org/wiki/Parco_Archeologico_dei_Tauriani", "url": "https://it.wikipedia.org/wiki/Parco_Archeologico_dei_Tauriani", "quote": "38°23′38.94″N 15°51′58.46″E", "outcome": "found"}, {"source": "https://topostext.org/place/384159UTau", "url": "https://topostext.org/place/384159UTau", "quote": "Latitude: 38.394440 Longitude: 15.871380", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0088)", "decision": "replace", "status": "CONFLICT", "reasoning": "The ruins of Tauriana lie on the Taureana plateau north-east of Palmi, where the Parco archeologico dei Tauriani stands (Italian Wikipedia: 38°23′38.94″N 15°51′58.46″E) and where ToposText (and Pleiades) place Tauriana (38.394440, 15.871380, 0.45 km away); the stored point is the arc-minute point of Palmi town, 3.3 km to the south-west, so it is replaced.", "value_page": null}]'::jsonb),
