    ('cc700fa7-64f3-46d6-9a97-7223f1c4d15d'::uuid, 'period_name', '3000 - 1500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s009-rollback:cc700fa7-64f3-46d6-9a97-7223f1c4d15d:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''500 BC - 1 AD'' restored on Ri Cruin Cairn, Kilmartin Glen', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-2200) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('cc700fa7-64f3-46d6-9a97-7223f1c4d15d'::uuid, 'period_start', '-2200', '-500', 'fields-wd1-2026-09-26b-s009-rollback:cc700fa7-64f3-46d6-9a97-7223f1c4d15d:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-500'' restored on Ri Cruin Cairn, Kilmartin Glen', '[{"source": "https://en.wikipedia.org/wiki/Kilmartin_Glen", "url": "https://en.wikipedia.org/wiki/Kilmartin_Glen", "quote": "This is the most southerly cairn in the linear cemetery, believed locally to be the possible burial place of a King. It was built between 2200 BC and 1950 BC", "outcome": "found"}, {"source": "https://www.explore-oban.com/what-to-do/attractions/kilmartin-glen/", "url": "https://www.explore-oban.com/what-to-do/attractions/kilmartin-glen/", "quote": "Ri Cruin Cairn: This is a Bronze Age burial cairn, constructed circa 2,000 years BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0023)", "decision": "replace", "status": "MISSING", "reasoning": "The Ri Cruin Cairn section of the English Wikipedia Kilmartin Glen article dates its construction to between 2200 BC and 1950 BC, and the Explore Oban visitor guide independently dates the Bronze Age cairn to circa 2000 BC; both fall in the 3000-1500 BC bucket, not the stored 500 BC - 1 AD one, so the start is -2200.", "value_page": null}]'::jsonb),
    ('cc700fa7-64f3-46d6-9a97-7223f1c4d15d'::uuid, 'source_url', 'https://fr.wikipedia.org/wiki/Cairn_de_Ri_Cruin', 'https://en.wikipedia.org/wiki/Kilmartin_Glen', 'fields-wd1-2026-09-26b-s009-rollback:cc700fa7-64f3-46d6-9a97-7223f1c4d15d:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Kilmartin_Glen'' restored on Ri Cruin Cairn, Kilmartin Glen', '[{"source": "https://fr.wikipedia.org/wiki/Cairn_de_Ri_Cruin", "url": "https://fr.wikipedia.org/wiki/Cairn_de_Ri_Cruin", "quote": "Le cairn de Ri Cruin fut découvert en 1830 et fouillé en 1870, 1929 et en 1936.", "outcome": "found"}, {"source": "https://portal.historicenvironment.scot/designation/SM90247", "url": "https://portal.historicenvironment.scot/designation/SM90247", "quote": "The monument comprises a Bronze Age round cairn which is situated in trees 210m S of Ri Cruin.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0124)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the article on the whole Kilmartin Glen area; Ri Cruin cairn has no English article, and the French Wikipedia article ''Cairn de Ri Cruin'' is the site''s own article, the same cairn Historic Environment Scotland schedules as SM90247.", "value_page": {"lang": "fr", "problem": null, "resolved_title": "Cairn de Ri Cruin", "unreadable": false, "wikibase_item": "Q1969530"}}]'::jsonb),
    ('cc775c2a-7c42-4cb9-a9ac-0bc6e3fbc0ec'::uuid, 'site_type', 'Tomb', 'Temple complex', 'fields-wd1-2026-09-26b-s009-rollback:cc775c2a-7c42-4cb9-a9ac-0bc6e3fbc0ec:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Temple complex'' restored on Nebi Samuel National Park', '[{"source": "https://www.biblewalks.com/nebisamuel", "url": "https://www.biblewalks.com/nebisamuel", "quote": "is the traditional tomb of prophet Samuel", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Tomb_of_Samuel", "url": "https://en.wikipedia.org/wiki/Tomb_of_Samuel", "quote": "is the traditional burial site of the biblical prophet Samuel", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0014)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both BibleWalks and Wikipedia (article Tomb of Samuel) describe Nebi Samuel as the traditional tomb and burial site of the prophet Samuel, on a hilltop with a Crusader-era building, not as a temple complex; Tomb is the most specific canonical type for what the sources say the site is.", "value_page": null}]'::jsonb),
    ('cc7e7e8a-ad91-4001-9849-bfcd41168369'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s009-rollback:cc7e7e8a-ad91-4001-9849-bfcd41168369:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1500 - 500 BC'' restored on Slate Hill Settlement', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('cc7e7e8a-ad91-4001-9849-bfcd41168369'::uuid, 'period_start', NULL, '-1000', 'fields-wd1-2026-09-26b-s009-rollback:cc7e7e8a-ad91-4001-9849-bfcd41168369:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-1000'' restored on Slate Hill Settlement', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0045)", "decision": "clear", "status": "MISSING", "reasoning": "Slate Hill has not been excavated and is dated only as Iron Age, from its form. The ''7th to 5th centuries BC'' on Wikipedia describes when this class of defended settlement first appears, not this site, and only one amateur blog suggests ''probably about 700-500 BC'', so no two sources date its start.", "value_page": null}]'::jsonb),
    ('cc7e7e8a-ad91-4001-9849-bfcd41168369'::uuid, 'site_type', 'Settlement', 'City/town/settlement', 'fields-wd1-2026-09-26b-s009-rollback:cc7e7e8a-ad91-4001-9849-bfcd41168369:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''City/town/settlement'' restored on Slate Hill Settlement', '[{"source": "https://en.wikipedia.org/wiki/Slate_Hill_Settlement", "url": "https://en.wikipedia.org/wiki/Slate_Hill_Settlement", "quote": "The site, a defended settlement dating from the Iron Age, is a scheduled monument.", "outcome": "found"}, {"source": "https://co-curate.ncl.ac.uk/slate-hill-settlement-earthworks-bolam-northumberland/", "url": "https://co-curate.ncl.ac.uk/slate-hill-settlement-earthworks-bolam-northumberland/", "quote": "Remains of a defended Iron Age settlement around the top of Slate Hill, just north of Bolam Lake in Northumberland.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0045)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia (after the Historic England scheduling) and Newcastle University''s Co-Curate both describe Slate Hill as a defended Iron Age settlement, a small enclosure for roundhouses, not a city or town. Settlement is the specific type.", "value_page": null}]'::jsonb),
    ('cc89fe8f-328b-470e-adcd-0d1244f28acf'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s009-rollback:cc89fe8f-328b-470e-adcd-0d1244f28acf:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1500 - 500 BC'' restored on Richmond Park', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('cc89fe8f-328b-470e-adcd-0d1244f28acf'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s009-rollback:cc89fe8f-328b-470e-adcd-0d1244f28acf:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-1500'' restored on Richmond Park', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0044)", "decision": "clear", "status": "MISSING", "reasoning": "The candidate mounds are dated only loosely (''may have been a Neolithic burial barrow'', ''possibly a round barrow'', ''most likely Bronze Age''), and Historic England itself says a prehistoric origin cannot be categorically confirmed; no two sources date a start year for this entry, so the stored -1500 is emptied.", "value_page": null}]'::jsonb),
    ('ccb3de8b-5c50-4204-ae6f-46cdda2e081d'::uuid, 'period_name', '1500 - 500 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s009-rollback:ccb3de8b-5c50-4204-ae6f-46cdda2e081d:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''3000 - 1500 BC'' restored on Ban Chiang', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1500) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('ccb3de8b-5c50-4204-ae6f-46cdda2e081d'::uuid, 'period_start', '-1500', '-3000', 'fields-wd1-2026-09-26b-s009-rollback:ccb3de8b-5c50-4204-ae6f-46cdda2e081d:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-3000'' restored on Ban Chiang', '[{"source": "https://en.wikipedia.org/wiki/Ban_Chiang", "url": "https://en.wikipedia.org/wiki/Ban_Chiang", "quote": "the results suggested that the initial settlement of Ban Chiang took place about 1500 BCE", "outcome": "found"}, {"source": "https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0137542", "url": "https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0137542", "quote": "There is only one EP I burial, and it has been dated between 1600–1450 BC (at 68.2% probability).", "outcome": "found"}, {"source": "https://www.unescotracker.net/sites/1057/ban-chiang-archaeological-site", "url": "https://www.unescotracker.net/sites/1057/ban-chiang-archaeological-site", "quote": "the site was continuously occupied from 1495BC until c. 900BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0024)", "decision": "replace", "status": "MISSING", "reasoning": "The stored -3000 rests on the discredited early radiocarbon and thermoluminescence dates; the Bayesian dating of human bone (Higham et al. 2015, PLOS ONE) puts the earliest Ban Chiang burial at 1600-1450 BC, English Wikipedia summarises the initial settlement as about 1500 BCE, and the World Heritage text repeated by UNESCO Heritage Tracker gives continuous occupation from 1495 BC, so the start is c. 1500 BC, in the 1500 - 500 BC bucket rather than the stored 3000 - 1500 BC one.", "value_page": null}]'::jsonb),
    ('ccf25f6a-36aa-458a-9d43-5b33ef8c119c'::uuid, 'period_name', NULL, '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s009-rollback:ccf25f6a-36aa-458a-9d43-5b33ef8c119c:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''3000 - 1500 BC'' restored on Borough Hill', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('ccf25f6a-36aa-458a-9d43-5b33ef8c119c'::uuid, 'period_start', NULL, '-3000', 'fields-wd1-2026-09-26b-s009-rollback:ccf25f6a-36aa-458a-9d43-5b33ef8c119c:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-3000'' restored on Borough Hill', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0028)", "decision": "clear", "status": "MISSING", "reasoning": "The sources give only period ranges: the Northamptonshire HER dates the barrows ''Bronze Age - 2350 BC to 701 BC'' and the hillfort''s possible first construction to the Late Bronze Age or the Iron Age, and the museum timeline mentions Neolithic finds. None dates the start of the site to a year, and the ranges span two buckets, so the start cannot be placed.", "value_page": null}]'::jsonb),
    ('ccf25f6a-36aa-458a-9d43-5b33ef8c119c'::uuid, 'site_type', 'Fort', 'Barrow', 'fields-wd1-2026-09-26b-s009-rollback:ccf25f6a-36aa-458a-9d43-5b33ef8c119c:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Barrow'' restored on Borough Hill', '[{"source": "https://her.northamptonshire.gov.uk/Monument/MNN3603", "url": "https://her.northamptonshire.gov.uk/Monument/MNN3603", "quote": "Chance finds indicate occupation during much of the later prehistoric period, culminating in the great hill fort itself.", "outcome": "found"}, {"source": "https://www.westnorthants.gov.uk/major-parks/borough-hill", "url": "https://www.westnorthants.gov.uk/major-parks/borough-hill", "quote": "Borough Hill has been used by humans for thousands of years and is the site of one of the largest ancient hill forts in the country.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0028)", "decision": "replace", "status": "CONFLICT", "reasoning": "The HER and the council describe the site above all as a great Iron Age hillfort (two hillforts, the large one enclosing the hilltop); the two Bronze Age barrows and the Roman barrow cemetery lie inside it, so the site as a whole is a fort, not a barrow.", "value_page": null}]'::jsonb),
    ('ccf25f6a-36aa-458a-9d43-5b33ef8c119c'::uuid, 'source_url', 'https://her.northamptonshire.gov.uk/Monument/MNN3603', 'https://en.wikipedia.org/wiki/Borough_Hill', 'fields-wd1-2026-09-26b-s009-rollback:ccf25f6a-36aa-458a-9d43-5b33ef8c119c:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Borough_Hill'' restored on Borough Hill', '[{"source": "https://her.northamptonshire.gov.uk/Monument/MNN3603", "url": "https://her.northamptonshire.gov.uk/Monument/MNN3603", "quote": "The hillfort known as Borough Hill Camp is one of the most important in the county, because of both the variety and the historical implications of the remains.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=4813", "url": "https://www.megalithic.co.uk/article.php?sid=4813", "quote": "Lidar image of the whole of the massive Borough Hillfort (Daventry)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0028)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Wikipedia article is about the hill; the Northamptonshire Historic Environment Record entry 631 ''Borough Hill Camp'' is the register entry for the hillfort monument itself, including the barrows and Roman remains within it, and loads as plain HTML.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('ccf40c39-5f83-4bc4-bf28-23d0a7e4fa59'::uuid, 'period_name', '3000 - 1500 BC', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s009-rollback:ccf40c39-5f83-4bc4-bf28-23d0a7e4fa59:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1500 - 500 BC'' restored on Ancient Eleon', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1700) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('ccf40c39-5f83-4bc4-bf28-23d0a7e4fa59'::uuid, 'period_start', '-1700', '-1500', 'fields-wd1-2026-09-26b-s009-rollback:ccf40c39-5f83-4bc4-bf28-23d0a7e4fa59:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-1500'' restored on Ancient Eleon', '[{"source": "https://wrap.warwick.ac.uk/id/eprint/189906/", "url": "https://wrap.warwick.ac.uk/id/eprint/189906/", "quote": "the particular case of Eleon in Greece during the late Middle Helladic to Late Helladic (LH) I period (c. 1700-1550 BCE)", "outcome": "found"}, {"source": "https://www.uvic.ca/humanities/greekroman/faculty/burkebrendan.php", "url": "https://www.uvic.ca/humanities/greekroman/faculty/burkebrendan.php", "quote": "Based on ceramics, the entire structure and burials seem confined to the early Mycenaean period, sometimes called the Shaft Grave period after the famous burials at Mycenae (ca 1700-1450 BCE).", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0009)", "decision": "replace", "status": "MISSING", "reasoning": "The excavators of ancient Eleon (Arma, eastern Boeotia) date the earliest securely attested activity, the Blue Stone Structure burial complex that begins in the late Middle Helladic, to c. 1700 BCE (Warwick repository abstract: c. 1700-1550 BCE; University of Victoria page of the co-director: ca 1700-1450 BCE); earlier Early Helladic II pottery occurs only in secondary contexts. The start is thus about 1700 BC, in the 3000 - 1500 BC bucket, not the stored -1500.", "value_page": null}]'::jsonb),
    ('ccf40c39-5f83-4bc4-bf28-23d0a7e4fa59'::uuid, 'site_type', 'Settlement', 'Polygonal masonry', 'fields-wd1-2026-09-26b-s009-rollback:ccf40c39-5f83-4bc4-bf28-23d0a7e4fa59:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Polygonal masonry'' restored on Ancient Eleon', '[{"source": "https://ebapexcavations.org/mycenaean/", "url": "https://ebapexcavations.org/mycenaean/", "quote": "Evidence for the Mycenaean settlement in Late Helladic periods is not surprising since the site of Eleon appears as e-re-o-ni on two Linear B tablets from Thebes", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Eleon", "url": "https://en.wikipedia.org/wiki/Eleon", "quote": "was a town in ancient Boeotia", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0060)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Eastern Boeotia Archaeological Project describes Eleon as a Mycenaean settlement and English Wikipedia as a town in ancient Boeotia, occupied from the Bronze Age with an Archaic polygonal wall as one feature; the site is a settlement, not a piece of polygonal masonry.", "value_page": null}]'::jsonb),
    ('ccfefb01-6020-4d87-8ae3-2fa94ba33837'::uuid, 'site_type', 'Sanctuary', 'Megalithic stones', 'fields-wd1-2026-09-26b-s009-rollback:ccfefb01-6020-4d87-8ae3-2fa94ba33837:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Megalithic stones'' restored on Didyma', '[{"source": "https://en.wikipedia.org/wiki/Didyma", "url": "https://en.wikipedia.org/wiki/Didyma", "quote": "was an ancient Greek sanctuary on the coast of Ionia in the domain of the famous city of Miletus", "outcome": "found"}, {"source": "https://topostext.org/place/374273SDid", "url": "https://topostext.org/place/374273SDid", "quote": "Δίδυμα - Didyma, Oracular sanctuary and temple of Didymaean Apollo near Miletos, modern Didim, Asia Minor", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0143)", "decision": "replace", "status": "CONFLICT", "reasoning": "Didyma is the oracular sanctuary of Apollo (with its temples) belonging to Miletus, as Wikipedia and ToposText state; it is not a megalithic monument, so the type becomes Sanctuary.", "value_page": null}]'::jsonb),
    ('cd2e38bd-c70e-4813-8ccd-0a567ab6a7ca'::uuid, 'site_type', 'Necropolis/tombs complex', 'Rock art', 'fields-wd1-2026-09-26b-s009-rollback:cd2e38bd-c70e-4813-8ccd-0a567ab6a7ca:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Rock art'' restored on Markahirka', '[{"source": "https://en.wikipedia.org/wiki/Markahirka", "url": "https://en.wikipedia.org/wiki/Markahirka", "quote": "is an archaeological site with cave paintings and stone tombs (chullpa) on a mountain of the same name in Peru.", "outcome": "found"}, {"source": "https://proyectohuariancash.org", "url": "https://proyectohuariancash.org", "quote": "Marcajirca has many funerary structures, known as chullpas, as well as caves, and semi-caves with human remains.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0020)", "decision": "replace", "status": "CONFLICT", "reasoning": "Markahirka (Marcajirca) is described by Wikipedia as a site of cave paintings and stone tombs (chullpa), and by the Huari-Ancash archaeological project that excavates it as a site with many funerary structures (chullpas, funerary caves and semi-caves, around 50, most with human bone remains). Rock art is only one minor element, not what two independent sources call the site; the dominant character is a complex of chullpa tombs and funerary caves, so the stored Rock art is replaced by Necropolis/tombs complex.", "value_page": null}]'::jsonb),
    ('cd7f64d3-c693-4955-88e3-638fbea42afd'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s009-rollback:cd7f64d3-c693-4955-88e3-638fbea42afd:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1500 - 500 BC'' restored on Wind Hill', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('cd7f64d3-c693-4955-88e3-638fbea42afd'::uuid, 'period_start', NULL, '-1000', 'fields-wd1-2026-09-26b-s009-rollback:cd7f64d3-c693-4955-88e3-638fbea42afd:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-1000'' restored on Wind Hill', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0048)", "decision": "clear", "status": "MISSING", "reasoning": "The Exmoor National Park HER and the National Trust record classify the promontory fort only as Iron Age (their period band of 800 BC to 42 AD), and the scheduling text speaks of the late Iron Age. The fort has no excavated or otherwise attested construction date, and the band spans two buckets, so no two sources date its start and the field is cleared.", "value_page": null}]'::jsonb),
    ('cd7f64d3-c693-4955-88e3-638fbea42afd'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s009-rollback:cd7f64d3-c693-4955-88e3-638fbea42afd:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Fortress/citadel'' restored on Wind Hill', '[{"source": "https://www.exmoorher.co.uk/Monument/MDE1236", "url": "https://www.exmoorher.co.uk/Monument/MDE1236", "quote": "An Iron Age univallate promontory fort on a west facing spur between the sea cliff to the north and the East Lyn Valley to the south.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Wind_Hill", "url": "https://en.wikipedia.org/wiki/Wind_Hill", "quote": "is the location of an Iron Age enclosure or \"spur\" hill fort", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0048)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Exmoor HER calls the site an Iron Age univallate promontory fort and Wikipedia calls it a spur hill fort; Fort is the most specific canonical type for a promontory hillfort.", "value_page": null}]'::jsonb),
    ('cd7f64d3-c693-4955-88e3-638fbea42afd'::uuid, 'source_url', 'https://www.exmoorher.co.uk/Monument/MDE1236', 'https://en.wikipedia.org/wiki/Wind_Hill', 'fields-wd1-2026-09-26b-s009-rollback:cd7f64d3-c693-4955-88e3-638fbea42afd:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Wind_Hill'' restored on Wind Hill', '[{"source": "https://www.exmoorher.co.uk/Monument/MDE1236", "url": "https://www.exmoorher.co.uk/Monument/MDE1236", "quote": "MDE1236 - Countisbury Castle or Wind Hill Promontory Fort (Monument)", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=4608", "url": "https://www.megalithic.co.uk/article.php?sid=4608", "quote": "Site Name: Wind Hill (Lynmouth) Alternative Name: Countisbury Castle", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0048)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the hill (its infobox describes a peak), and no Wikipedia article covers the fort itself. The Exmoor National Park Historic Environment Record entry MDE1236 is about the fort, Countisbury Castle or Wind Hill Promontory Fort, a name the Megalithic Portal confirms.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('ce14b760-db1b-4b4d-93eb-8654952d9450'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s009-rollback:ce14b760-db1b-4b4d-93eb-8654952d9450:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''4500 - 3000 BC'' restored on Thebes, Greece', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('ce14b760-db1b-4b4d-93eb-8654952d9450'::uuid, 'period_start', NULL, '-4000', 'fields-wd1-2026-09-26b-s009-rollback:ce14b760-db1b-4b4d-93eb-8654952d9450:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-4000'' restored on Thebes, Greece', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0073)", "decision": "clear", "status": "CONFLICT", "reasoning": "The Greek Ministry of Culture (Odysseus: ''Occupation began in Neolithic times (Pyri) and the settlement was already strong in Early Helladic (3000 - 2000 B.C.)''), the Foundation of the Hellenic World''s Boeotia encyclopedia and the Thebes Museum all put the first occupation of Thebes in the Neolithic, but none gives it a date; the dated statements (Early Helladic 3000-2000 BC; Golden Greece''s ''continuously inhabited since the early Bronze Age (3rd millennium BC)''; Wikidata''s -2000) describe later phases that the Neolithic start precedes. No two independent sources date the start itself, so neither the stored -4000 nor a 3rd-millennium value can be sourced, and the field is cleared.", "value_page": null}]'::jsonb),
    ('ce4058e7-7631-40ad-beb1-188e3cd27232'::uuid, 'geom', 'SRID=4326;POINT(15.241689 41.7637)', '0101000020E6100000092757B64FD52D40E5DE91366DE64440', 'fields-wd1-2026-09-26b-s009-rollback:ce4058e7-7631-40ad-beb1-188e3cd27232:geom', 'rollback of fields-wd1-2026-09-26b-s009: geom ''0101000020E6100000092757B64FD52D40E5DE91366DE64440'' restored on Teanum Apulum', '[{"source": "https://it.wikipedia.org/wiki/Teanum_Apulum", "url": "https://it.wikipedia.org/wiki/Teanum_Apulum", "quote": "41°45′49.32″N 15°14′30.08″E", "outcome": "found"}, {"source": "https://topostext.org/place/418152UTea", "url": "https://topostext.org/place/418152UTea", "quote": "Latitude: 41.771000 Longitude: 15.237000", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0088)", "decision": "replace", "status": "CONFLICT", "reasoning": "Teanum Apulum lies on the hills south of the Fortore north-west of San Paolo di Civitate: Italian Wikipedia gives 41°45′49.32″N 15°14′30.08″E and ToposText 41.771, 15.237 (0.9 km away; the Digital Atlas of the Roman Empire agrees). The stored point is 27 km to the west, at Larino in Molise, so it is replaced.", "value_page": null}]'::jsonb),
    ('ce4058e7-7631-40ad-beb1-188e3cd27232'::uuid, 'lat', '41.7637', '41.80020792124359', 'fields-wd1-2026-09-26b-s009-rollback:ce4058e7-7631-40ad-beb1-188e3cd27232:lat', 'rollback of fields-wd1-2026-09-26b-s009: lat ''41.80020792124359'' restored on Teanum Apulum', '[{"source": "https://it.wikipedia.org/wiki/Teanum_Apulum", "url": "https://it.wikipedia.org/wiki/Teanum_Apulum", "quote": "41°45′49.32″N 15°14′30.08″E", "outcome": "found"}, {"source": "https://topostext.org/place/418152UTea", "url": "https://topostext.org/place/418152UTea", "quote": "Latitude: 41.771000 Longitude: 15.237000", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0088)", "decision": "replace", "status": "CONFLICT", "reasoning": "Teanum Apulum lies on the hills south of the Fortore north-west of San Paolo di Civitate: Italian Wikipedia gives 41°45′49.32″N 15°14′30.08″E and ToposText 41.771, 15.237 (0.9 km away; the Digital Atlas of the Roman Empire agrees). The stored point is 27 km to the west, at Larino in Molise, so it is replaced.", "value_page": null}]'::jsonb),
    ('ce4058e7-7631-40ad-beb1-188e3cd27232'::uuid, 'lon', '15.241689', '14.916623781336527', 'fields-wd1-2026-09-26b-s009-rollback:ce4058e7-7631-40ad-beb1-188e3cd27232:lon', 'rollback of fields-wd1-2026-09-26b-s009: lon ''14.916623781336527'' restored on Teanum Apulum', '[{"source": "https://it.wikipedia.org/wiki/Teanum_Apulum", "url": "https://it.wikipedia.org/wiki/Teanum_Apulum", "quote": "41°45′49.32″N 15°14′30.08″E", "outcome": "found"}, {"source": "https://topostext.org/place/418152UTea", "url": "https://topostext.org/place/418152UTea", "quote": "Latitude: 41.771000 Longitude: 15.237000", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0088)", "decision": "replace", "status": "CONFLICT", "reasoning": "Teanum Apulum lies on the hills south of the Fortore north-west of San Paolo di Civitate: Italian Wikipedia gives 41°45′49.32″N 15°14′30.08″E and ToposText 41.771, 15.237 (0.9 km away; the Digital Atlas of the Roman Empire agrees). The stored point is 27 km to the west, at Larino in Molise, so it is replaced.", "value_page": null}]'::jsonb),
    ('ce4058e7-7631-40ad-beb1-188e3cd27232'::uuid, 'period_name', '1500 - 500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s009-rollback:ce4058e7-7631-40ad-beb1-188e3cd27232:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''500 BC - 1 AD'' restored on Teanum Apulum', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-900) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('ce4058e7-7631-40ad-beb1-188e3cd27232'::uuid, 'period_start', '-900', '-500', 'fields-wd1-2026-09-26b-s009-rollback:ce4058e7-7631-40ad-beb1-188e3cd27232:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-500'' restored on Teanum Apulum', '[{"source": "https://it.wikipedia.org/wiki/Teanum_Apulum", "url": "https://it.wikipedia.org/wiki/Teanum_Apulum", "quote": "fu uno dei più importanti insediamenti della Daunia fondato nel IX secolo a.C.", "outcome": "found"}, {"source": "https://www.sicaltotavoliere.it/memoria/teanum-apulum/", "url": "https://www.sicaltotavoliere.it/memoria/teanum-apulum/", "quote": "risalente alla prima età del Ferro, tra XI-IX secolo a.C.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0088)", "decision": "replace", "status": "MISSING", "reasoning": "Italian Wikipedia says the Daunian settlement of Tiati, later Teanum Apulum, was founded in the 9th century BC, and SiCAT dates the site to the early Iron Age, 11th-9th century BC; the start therefore lies in the 1500 - 500 BC bucket, not in the stored 500 BC - 1 AD, which reflects only the Roman conquest of 318 BC.", "value_page": null}]'::jsonb),
    ('ce507a92-23cf-49e2-ada8-734277dee902'::uuid, 'period_name', '4500 - 3000 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s009-rollback:ce507a92-23cf-49e2-ada8-734277dee902:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''500 BC - 1 AD'' restored on The Linear Cemetery, Kilmartin Glen', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3700) = ''4500 - 3000 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('ce507a92-23cf-49e2-ada8-734277dee902'::uuid, 'period_start', '-3700', '-500', 'fields-wd1-2026-09-26b-s009-rollback:ce507a92-23cf-49e2-ada8-734277dee902:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-500'' restored on The Linear Cemetery, Kilmartin Glen', '[{"source": "https://www.kilmartin.org/self-guided-trail", "url": "https://www.kilmartin.org/self-guided-trail", "quote": "This is one of the oldest monuments in the glen built over 5,000 years ago (3700-3600BC)", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Kilmartin_Glen", "url": "https://en.wikipedia.org/wiki/Kilmartin_Glen", "quote": "Nether Largie South is the oldest monument of the linear cemetery. It is a Neolithic chambered cairn of the Clyde type, probably dating from the fourth millennium BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0124)", "decision": "replace", "status": "MISSING", "reasoning": "The cemetery''s oldest monument, Nether Largie South chambered cairn, was built in 3700-3600 BC according to Kilmartin Museum and in the fourth millennium BC according to Wikipedia; the site''s history thus begins c. 3700 BC, in the 4500-3000 BC bucket, not in the stored 500 BC - 1 AD one.", "value_page": null}]'::jsonb),
    ('ce507a92-23cf-49e2-ada8-734277dee902'::uuid, 'site_type', 'Cemetery', 'Cairn', 'fields-wd1-2026-09-26b-s009-rollback:ce507a92-23cf-49e2-ada8-734277dee902:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Cairn'' restored on The Linear Cemetery, Kilmartin Glen', '[{"source": "https://www.mysteriousbritain.co.uk/ancient-sites/kilmartin-linear-cemetery/", "url": "https://www.mysteriousbritain.co.uk/ancient-sites/kilmartin-linear-cemetery/", "quote": "The linear cemetery consists of five cairns dating from the Bronze Age, some of which overlay older sites.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Kilmartin_Glen", "url": "https://en.wikipedia.org/wiki/Kilmartin_Glen", "quote": "a \"linear cemetery\" comprising five burial cairns", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0124)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is not a single cairn but a prehistoric cemetery of five burial cairns laid out in a line, as both Mysterious Britain and Wikipedia describe it, so Cemetery is the fitting type.", "value_page": null}]'::jsonb),
    ('ce507a92-23cf-49e2-ada8-734277dee902'::uuid, 'source_url', 'https://www.mysteriousbritain.co.uk/ancient-sites/kilmartin-linear-cemetery/', 'https://en.wikipedia.org/wiki/Kilmartin_Glen', 'fields-wd1-2026-09-26b-s009-rollback:ce507a92-23cf-49e2-ada8-734277dee902:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Kilmartin_Glen'' restored on The Linear Cemetery, Kilmartin Glen', '[{"source": "https://www.mysteriousbritain.co.uk/ancient-sites/kilmartin-linear-cemetery/", "url": "https://www.mysteriousbritain.co.uk/ancient-sites/kilmartin-linear-cemetery/", "quote": "The most easily accessible group of sites form the Kilmartin Linear Cemetery, a collection of Bronze Age cairns, all of which can be reached on foot from the museum at Kilmartin House.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Kilmartin_Glen", "url": "https://en.wikipedia.org/wiki/Kilmartin_Glen", "quote": "Nether Largie South is the oldest monument of the linear cemetery.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0124)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the Wikipedia article on the whole Kilmartin Glen area; the linear cemetery has no Wikipedia article or register entry of its own, and Mysterious Britain''s ''Kilmartin Linear Cemetery'' page is devoted to this very group of cairns.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('ce64147f-624e-474d-92af-b6e84001d54d'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s009-rollback:ce64147f-624e-474d-92af-b6e84001d54d:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1 - 500 AD'' restored on Dun Cuier', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('ce64147f-624e-474d-92af-b6e84001d54d'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s009-rollback:ce64147f-624e-474d-92af-b6e84001d54d:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''1'' restored on Dun Cuier', '[{"source": "WD1 decision (counted, round 1, wd1-r1-b0022)", "decision": "clear", "status": "MISSING", "reasoning": "Dun Cuier has no securely dated start: the Western Isles Historic Environment Record gives only a broad period of 0 AD to 800 AD with excavated finds of the 4th to 7th centuries AD, German Wikipedia says the structure was in use from the first millennium BC, and Dutch Wikipedia states there is no precise dating and that the 1950s finds were mixed across periods, so the stored value 1 is not attested and the field is emptied.", "value_page": null}]'::jsonb),
    ('ce64147f-624e-474d-92af-b6e84001d54d'::uuid, 'source_url', 'https://de.wikipedia.org/wiki/Dun_Cuier', 'https://en.wikipedia.org/wiki/Iron_Age', 'fields-wd1-2026-09-26b-s009-rollback:ce64147f-624e-474d-92af-b6e84001d54d:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Iron_Age'' restored on Dun Cuier', '[{"source": "https://de.wikipedia.org/wiki/Dun_Cuier", "url": "https://de.wikipedia.org/wiki/Dun_Cuier", "quote": "Dun Cuier ist eine von mehreren derartigen Anlagen (Dun Scurrival) auf Barra, die aber meist nicht ausgegraben sind.", "outcome": "found"}, {"source": "https://her.cne-siar.gov.uk/Monument/MWE9710", "url": "https://her.cne-siar.gov.uk/Monument/MWE9710", "quote": "Dun Cuier, a fairly well preserved galleried dun, was excavated by Young between 1953 and 1955.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0022)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the Iron Age period article; the site has no English Wikipedia article, but German Wikipedia has an article on Dun Cuier on Barra, and the Western Isles Historic Environment Record entry 522 describes the same dun.", "value_page": {"lang": "de", "problem": null, "resolved_title": "Dun Cuier", "unreadable": false, "wikibase_item": "Q1265207"}}]'::jsonb),
    ('ce733a7d-a3e2-463d-b09e-2bdac5ea6dcb'::uuid, 'geom', 'SRID=4326;POINT(38.54389 27.62972)', '0101000020E610000048691EFECEAF02406916E2213F6E4840', 'fields-wd1-2026-09-26b-s009-rollback:ce733a7d-a3e2-463d-b09e-2bdac5ea6dcb:geom', 'rollback of fields-wd1-2026-09-26b-s009: geom ''0101000020E610000048691EFECEAF02406916E2213F6E4840'' restored on Tayma Stones', '[{"source": "https://en.wikipedia.org/wiki/Tayma", "url": "https://en.wikipedia.org/wiki/Tayma", "quote": "27.62972°N 38.54389°E", "outcome": "found"}, {"source": "https://www.geonames.org/101516/tayma.html", "url": "https://www.geonames.org/101516/tayma.html", "quote": "Coordinates 27.62233, 38.53882", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0121)", "decision": "replace", "status": "MISSING", "reasoning": "The Tayma stones are inscriptions found in the oasis of Tayma (the Louvre gives the place of discovery of its stele as Teima). The stored point is the Louvre in Paris, the museum that keeps them, about 4,000 km from the site. Wikipedia and GeoNames place Tayma 0.96 km apart, so the point becomes Wikipedia''s Tayma point.", "value_page": null}]'::jsonb),
