    ('ce733a7d-a3e2-463d-b09e-2bdac5ea6dcb'::uuid, 'period_name', '500 BC - 1 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s009-rollback:ce733a7d-a3e2-463d-b09e-2bdac5ea6dcb:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1500 - 500 BC'' restored on Tayma Stones', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-500) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('ce733a7d-a3e2-463d-b09e-2bdac5ea6dcb'::uuid, 'period_start', '-500', '-1500', 'fields-wd1-2026-09-26b-s009-rollback:ce733a7d-a3e2-463d-b09e-2bdac5ea6dcb:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-1500'' restored on Tayma Stones', '[{"source": "https://collections.louvre.fr/en/ark:/53355/cl010120341", "url": "https://collections.louvre.fr/en/ark:/53355/cl010120341", "quote": "Stèle de Teima -500 / -400 (Ve s. av. J.-C.) Place of discovery : Teima", "outcome": "found"}, {"source": "https://cojs.org/aramaic_stelae-_5th_century_bce/", "url": "https://cojs.org/aramaic_stelae-_5th_century_bce/", "quote": "Aramaic Stelae, 5th century BCE The discoveries, a century apart, of two fifth-century B.C. stelae", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0121)", "decision": "replace", "status": "MISSING", "reasoning": "The Louvre dates the principal Tayma stele to -500/-400 (5th century BC), and the Center for Online Judaic Studies dates both Tayma Aramaic stelae to the 5th century BCE. Wikipedia gives only a looser ''approximately the 5th and 6th centuries BCE''. The start is -500, in the 500 BC - 1 AD bucket, not the stored 1500 - 500 BC.", "value_page": null}]'::jsonb),
    ('ce733a7d-a3e2-463d-b09e-2bdac5ea6dcb'::uuid, 'site_type', 'Inscription', 'Rock relief/carving', 'fields-wd1-2026-09-26b-s009-rollback:ce733a7d-a3e2-463d-b09e-2bdac5ea6dcb:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Rock relief/carving'' restored on Tayma Stones', '[{"source": "https://en.wikipedia.org/wiki/Tayma_stones", "url": "https://en.wikipedia.org/wiki/Tayma_stones", "quote": "Achaemenid-era Aramaic inscriptions", "outcome": "found"}, {"source": "https://cojs.org/aramaic_stelae-_5th_century_bce/", "url": "https://cojs.org/aramaic_stelae-_5th_century_bce/", "quote": "The discoveries, a century apart, of two fifth-century B.C. stelae (monuments) inscribed in Aramaic at the oasis of Tayma’ (Biblical Tema) cast light on a time when the Babylonian empire extended deep into the Arabian peninsula.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0121)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia defines the Tayma stones as a collection of Aramaic inscriptions, and the Center for Online Judaic Studies describes them as stelae inscribed in Aramaic. They are movable inscribed stones, not a relief carved into living rock, so the type is Inscription, not Rock relief/carving.", "value_page": null}]'::jsonb),
    ('ce7db300-8777-425d-917a-2f6d9f325b58'::uuid, 'site_type', 'City', 'Temple complex', 'fields-wd1-2026-09-26b-s009-rollback:ce7db300-8777-425d-917a-2f6d9f325b58:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Temple complex'' restored on Caesarea Philippi', '[{"source": "https://en.wikipedia.org/wiki/Banias", "url": "https://en.wikipedia.org/wiki/Banias", "quote": "In 3 BCE, Herod''s son, Philip (also known as Philip the Tetrarch) founded a city which became his administrative capital", "outcome": "found"}, {"source": "https://walkswithjesus.org/archaeology/sites/caesarea-philippi-banias/", "url": "https://walkswithjesus.org/archaeology/sites/caesarea-philippi-banias/", "quote": "sit the ruins of the city the Gospels call Caesarea Philippi", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0083)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site entry is Caesarea Philippi, the city founded by Philip the Tetrarch as his capital, which contains the sanctuary of Pan as one of its parts; the sources describe it as a city, so City fits the named site better than Temple complex.", "value_page": null}]'::jsonb),
    ('ce9c68cf-97b7-4ef2-8301-0a3907d2608d'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s009-rollback:ce9c68cf-97b7-4ef2-8301-0a3907d2608d:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1500 - 500 BC'' restored on Stockland Castle', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('ce9c68cf-97b7-4ef2-8301-0a3907d2608d'::uuid, 'period_start', NULL, '-1000', 'fields-wd1-2026-09-26b-s009-rollback:ce9c68cf-97b7-4ef2-8301-0a3907d2608d:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-1000'' restored on Stockland Castle', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0046)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia and the Megalithic Portal call the hillfort Iron Age and the Historic England listing (mirrored) ''prehistoric'', but no source gives a year, century or millennium for this fort''s construction, so the stored -1000 cannot be sourced.", "value_page": null}]'::jsonb),
    ('ce9c68cf-97b7-4ef2-8301-0a3907d2608d'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s009-rollback:ce9c68cf-97b7-4ef2-8301-0a3907d2608d:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Fortress/citadel'' restored on Stockland Castle', '[{"source": "https://en.wikipedia.org/wiki/Stockland_Castle", "url": "https://en.wikipedia.org/wiki/Stockland_Castle", "quote": "Stockland Castle is the name given to two Iron Age hill forts on Stockland Hill close to Stockland, Devon, England.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=29181", "url": "https://www.megalithic.co.uk/article.php?sid=29181", "quote": "An Iron Age hillfort in Devon which originally had 3 rings of ditches and ramparts.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0008)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia says Stockland Castle names two Iron Age hill forts on Stockland Hill near Stockland, Devon, and the Megalithic Portal independently lists Stockland Great Castle (Dalwood, Devon, 50.8179 N 3.0998 W, the stored point) as an Iron Age hillfort; it is a hillfort, so Fort is the closest canonical type and ''Fortress/citadel'' is not supported.", "value_page": null}]'::jsonb),
