    ('ceff34a3-d6a5-4d8c-8c58-4a8cc27460a5'::uuid, 'geom', 'SRID=4326;POINT(25.16306 35.29806)', '0101000020E61000008BC8B77D0F23394011EDCFE85BAB4140', 'fields-wd1-2026-09-26b-s009-rollback:ceff34a3-d6a5-4d8c-8c58-4a8cc27460a5:geom', 'rollback of fields-wd1-2026-09-26b-s009: geom ''0101000020E61000008BC8B77D0F23394011EDCFE85BAB4140'' restored on Bull-Leaping Fresco', '[{"source": "https://en.wikipedia.org/wiki/Knossos", "url": "https://en.wikipedia.org/wiki/Knossos", "quote": "35°17′53″N 25°9′47″E", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=10024", "url": "https://www.megalithic.co.uk/article.php?sid=10024", "quote": "Latitude: 35.297953N Longitude: 25.163373E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0063)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored point is the Heraklion Archaeological Museum, which now keeps the fresco. The fresco''s own place is the upper storey of the East Wing of the Minoan palace at Knossos (Wikipedia; Ministry of Culture: ''Provenance: Knossos, East Wing of the palace''), about 5 km away. Wikipedia and the Megalithic Portal give the palace at Knossos within 0.03 km of each other.", "value_page": null}]'::jsonb),
