    ('ceff34a3-d6a5-4d8c-8c58-4a8cc27460a5'::uuid, 'period_name', '1500 - 500 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s009-rollback:ceff34a3-d6a5-4d8c-8c58-4a8cc27460a5:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''3000 - 1500 BC'' restored on Bull-Leaping Fresco', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1450) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('ceff34a3-d6a5-4d8c-8c58-4a8cc27460a5'::uuid, 'period_start', '-1450', '-3000', 'fields-wd1-2026-09-26b-s009-rollback:ceff34a3-d6a5-4d8c-8c58-4a8cc27460a5:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-3000'' restored on Bull-Leaping Fresco', '[{"source": "https://olympicgames.culture.gov.gr/en/aparxes/toixografia_twn_tavrokathapsion.html", "url": "https://olympicgames.culture.gov.gr/en/aparxes/toixografia_twn_tavrokathapsion.html", "quote": "Heraklion Archaeological Museum, inv. n. Τ. 14 1450 – 1400 BC (Late LΜ ΙΒ – LΜ ΙΙ)", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Bull-Leaping_Fresco", "url": "https://en.wikipedia.org/wiki/Bull-Leaping_Fresco", "quote": "Year 1450 BC", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0063)", "decision": "replace", "status": "MISSING", "reasoning": "The Greek Ministry of Culture dates the Taureador (Bull-Leaping) Fresco to 1450-1400 BC (late LM IB - LM II), and Wikipedia gives 1450 BC. The start is c. 1450 BC, in the 1500-500 BC bucket, not the stored -3000.", "value_page": null}]'::jsonb),
    ('ceff34a3-d6a5-4d8c-8c58-4a8cc27460a5'::uuid, 'site_type', NULL, 'Rock relief/carving', 'fields-wd1-2026-09-26b-s009-rollback:ceff34a3-d6a5-4d8c-8c58-4a8cc27460a5:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Rock relief/carving'' restored on Bull-Leaping Fresco', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0063)", "decision": "clear", "status": "CONFLICT", "reasoning": "Wikipedia and the Ministry of Culture describe the entry as a Minoan fresco, a painted stucco relief panel from a room in the palace at Knossos, not a rock relief or carving. No canonical type describes a wall painting, and ''Palace'' would describe Knossos rather than the fresco, so the field is emptied.", "value_page": null}]'::jsonb),
    ('cf3b581a-c47f-41c6-9922-48c6e3b8d3a0'::uuid, 'source_url', 'https://medialampung.disway.id/seni-dan-budaya/read/699757/situs-tebingtinggi-dan-warisan-megalitik-pagar-alam', 'https://kebudayaan-kemdikbud-go-id.translate.goog/bpcbjambi/situs-tebingtinggi/?_x_tr_sl=id&_x_tr_tl=en&_x_tr_hl=en&_x_tr_pto=sc', 'fields-wd1-2026-09-26b-s009-rollback:cf3b581a-c47f-41c6-9922-48c6e3b8d3a0:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://kebudayaan-kemdikbud-go-id.translate.goog/bpcbjambi/situs-tebingtinggi/?_x_tr_sl=id&_x_tr_tl=en&_x_tr_hl=en&_x_tr_pto=sc'' restored on Situs Megalit Tebing Tinggi', '[{"source": "https://medialampung.disway.id/seni-dan-budaya/read/699757/situs-tebingtinggi-dan-warisan-megalitik-pagar-alam", "url": "https://medialampung.disway.id/seni-dan-budaya/read/699757/situs-tebingtinggi-dan-warisan-megalitik-pagar-alam", "quote": "Tinggalan utama di Situs Tebingtinggi berupa batu-batu besar yang telah mengalami proses pengolahan oleh tangan manusia.", "outcome": "found"}, {"source": "https://kumparan.com/melisaxn23/fakta-dan-fiksi-kedudukan-mitos-dan-sejarah-di-situs-tebing-tinggi-243Fhgflqq2", "url": "https://kumparan.com/melisaxn23/fakta-dan-fiksi-kedudukan-mitos-dan-sejarah-di-situs-tebing-tinggi-243Fhgflqq2", "quote": "Situs Tebing Tinggi merupakan kawasan megalitik yang ada di dusun Tebing Tinggi, Kelurahan Lubuk Buntak, Kecamatan Dempo Selatan, Kota Pagar Alam, Sumatra Selatan.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0079)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is a Google Translate proxy of a BPCB Jambi page whose host no longer resolves. Media Lampung''s article is devoted to this very site (Situs Tebingtinggi, Pagar Alam) and loads as plain HTML; Kumparan independently describes the same site in Lubuk Buntak, Dempo Selatan.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('cf614eac-2835-4d18-9904-13b9c47c1ed2'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Nazca_lines', 'https://www.history.com/topics/south-america/nazca-lines', 'fields-wd1-2026-09-26b-s009-rollback:cf614eac-2835-4d18-9904-13b9c47c1ed2:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://www.history.com/topics/south-america/nazca-lines'' restored on Nazca Lines', '[{"source": "https://en.wikipedia.org/wiki/Nazca_lines", "url": "https://en.wikipedia.org/wiki/Nazca_lines", "quote": "are a group of geoglyphs made in the soil of the Nazca Desert in southern", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Nazca_lines", "url": "https://en.wikipedia.org/wiki/Nazca_lines", "quote": "There are two major phases of the Nazca lines,", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=16337", "url": "https://www.megalithic.co.uk/article.php?sid=16337", "quote": "Site Name: Nazca Lines Country: Peru", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0112)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored history.com URL now redirects to the German History Channel home page; the English Wikipedia article on the Nazca lines is the site''s own article, and the Megalithic Portal describes the same site.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Nazca lines", "unreadable": false, "wikibase_item": "Q2620036"}}]'::jsonb),
    ('cf8b5d56-cbc8-4550-bd77-4dc259020bad'::uuid, 'period_name', NULL, '< 4500 BC', 'fields-wd1-2026-09-26b-s009-rollback:cf8b5d56-cbc8-4550-bd77-4dc259020bad:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''< 4500 BC'' restored on Wurdi Youang Stone Arrangement', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('cf8b5d56-cbc8-4550-bd77-4dc259020bad'::uuid, 'period_start', NULL, '-9000', 'fields-wd1-2026-09-26b-s009-rollback:cf8b5d56-cbc8-4550-bd77-4dc259020bad:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-9000'' restored on Wurdi Youang Stone Arrangement', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0006)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia says the purpose, use and age of the arrangement are not known, and the ICOMOS-IAU thematic study case study says its construction date is unknown and could be anywhere from c. 25000 BC to about 1835 AD; the 11,000-year figure is only a suggestion from dates at nearby sites. No source dates the start, so the field is emptied.", "value_page": null}]'::jsonb),
    ('cfaf38c0-0365-4841-a42a-1cfc5c45c42d'::uuid, 'site_type', 'Temple', 'Megalithic stones', 'fields-wd1-2026-09-26b-s009-rollback:cfaf38c0-0365-4841-a42a-1cfc5c45c42d:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Megalithic stones'' restored on Archaeological site Puma Punku', '[{"source": "https://interactive.archaeology.org/tiwanaku/project/pumapunku1.html", "url": "https://interactive.archaeology.org/tiwanaku/project/pumapunku1.html", "quote": "Investigations at the Pumapunku Temple", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=29418", "url": "https://www.megalithic.co.uk/article.php?sid=29418", "quote": "Type: Ancient Temple", "outcome": "found"}, {"source": "https://projects.idialab.org/pumapunku/", "url": "https://projects.idialab.org/pumapunku/", "quote": "a virtual reconstruction of the Pumapunku Temple, part of the archaeological site of Tiwanaku in present-day Bolivia", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0012)", "decision": "replace", "status": "CONFLICT", "reasoning": "Archaeology magazine''s Tiwanaku dig pages, the Megalithic Portal and Ball State''s IDIA Lab all describe Pumapunku as a temple (a terraced platform mound with a monumental structure on top); ''Megalithic stones'' only names its building material, so Temple is the more specific type.", "value_page": null}]'::jsonb),
    ('cfb36f32-10c1-477e-8a10-203dea937c00'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s009-rollback:cfb36f32-10c1-477e-8a10-203dea937c00:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1 - 500 AD'' restored on Kuntuyuq', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('cfb36f32-10c1-477e-8a10-203dea937c00'::uuid, 'period_start', NULL, '300', 'fields-wd1-2026-09-26b-s009-rollback:cfb36f32-10c1-477e-8a10-203dea937c00:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''300'' restored on Kuntuyuq', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0111)", "decision": "clear", "status": "MISSING", "reasoning": "Only Peru''s MINCETUR inventory dates the paintings (approx. 6,000 to 5,000 BC, copied verbatim by datahub.drago.pe); no second independent source dates the site, and the stored 300 AD is contradicted by that estimate, so the field is emptied.", "value_page": null}]'::jsonb),
    ('cfc78356-fc53-48b9-b1d5-6bb1c7f86426'::uuid, 'site_type', 'Sanctuary', 'City/town/settlement', 'fields-wd1-2026-09-26b-s009-rollback:cfc78356-fc53-48b9-b1d5-6bb1c7f86426:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''City/town/settlement'' restored on Ναός Σωτήρου Διός', '[{"source": "https://topostext.org/place/374221SZSo", "url": "https://topostext.org/place/374221SZSo", "quote": "Zeus Soter, Large colonnaded sanctuary in Megalopolis near the Helisson river", "outcome": "found"}, {"source": "https://www.roamintheempire.com/index.php/2025/07/09/megalopolis/", "url": "https://www.roamintheempire.com/index.php/2025/07/09/megalopolis/", "quote": "This sanctuary with a porticos, monumental entrances, and a temple located on the western side", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0074)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the colonnaded sanctuary of Zeus Soter with its temple inside Megalopolis, not the city itself; ToposText and Roamin'' the Empire both describe it as a sanctuary.", "value_page": null}]'::jsonb),
    ('cfc78356-fc53-48b9-b1d5-6bb1c7f86426'::uuid, 'source_url', 'https://topostext.org/place/374221SZSo', 'https://en.wikipedia.org/wiki/Megalopolis,_Greece', 'fields-wd1-2026-09-26b-s009-rollback:cfc78356-fc53-48b9-b1d5-6bb1c7f86426:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Megalopolis,_Greece'' restored on Ναός Σωτήρου Διός', '[{"source": "https://topostext.org/place/374221SZSo", "url": "https://topostext.org/place/374221SZSo", "quote": "Zeus Soter sanctuary (Megalopolis)", "outcome": "found"}, {"source": "http://odysseus.culture.gr/h/3/gh352.jsp?obj_id=2558", "url": "http://odysseus.culture.gr/h/3/gh352.jsp?obj_id=2558", "quote": "το ιερό του Διός Σωτήρος", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0011)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia page is the article of the town of Megalopolis, not of the sanctuary (which has no Wikipedia article); the ToposText place page is the entry of this very sanctuary (Zeus Soter sanctuary, Megalopolis, near the Helisson river), and the Greek Ministry of Culture page on ancient Megalopolis independently names the ιερό του Διός Σωτήρος in the agora north of the river.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
