    ('cfdbdb6f-7420-49f2-9f19-8922851ddc24'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s009-rollback:cfdbdb6f-7420-49f2-9f19-8922851ddc24:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1 - 500 AD'' restored on Kinichná', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
