    ('d013bd60-0008-4319-85ff-1523f13edf5b'::uuid, 'period_start', NULL, '-3000', 'fields-wd1-2026-09-26b-s009-rollback:d013bd60-0008-4319-85ff-1523f13edf5b:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-3000'' restored on Trink Hill', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0047)", "decision": "clear", "status": "MISSING", "reasoning": "No source found dates the Trink Hill round barrow: the Megalithic Portal files it only under ''Neolithic and Bronze Age'' and Wikipedia gives no date, so no two sources give a year, century or millennium and the field is cleared.", "value_page": null}]'::jsonb),
    ('d013bd60-0008-4319-85ff-1523f13edf5b'::uuid, 'source_url', 'https://www.megalithic.co.uk/article.php?sid=20224', 'https://en.wikipedia.org/wiki/Trink_Hill', 'fields-wd1-2026-09-26b-s009-rollback:d013bd60-0008-4319-85ff-1523f13edf5b:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Trink_Hill'' restored on Trink Hill', '[{"source": "https://www.megalithic.co.uk/article.php?sid=20224", "url": "https://www.megalithic.co.uk/article.php?sid=20224", "quote": "At the summit of Trink Hill is a round barrow, intruded upon by a drystone wall and Ordnance Survey triangulation pillar.", "outcome": "found"}, {"source": "https://www.intocornwall.com/engine/azabout.asp?guide=Trink%20Hill", "url": "https://www.intocornwall.com/engine/azabout.asp?guide=Trink%20Hill", "quote": "Trink Hill is located on the Land''s End peninsula between the hamlets of Trink and Cripplesease, The hill is a prominent landmark and an archaeological site with an OS triangulation point on its summit.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0047)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the hill; the Megalithic Portal record ''Trink Hill'' (type Round Barrow(s)) is a page about the barrow itself and loads as plain HTML.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('d1720193-07a3-495c-ba7e-823426aa4f17'::uuid, 'period_name', '500 - 1000 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s009-rollback:d1720193-07a3-495c-ba7e-823426aa4f17:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1 - 500 AD'' restored on Quiahuiztlan', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(800) = ''500 - 1000 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d1720193-07a3-495c-ba7e-823426aa4f17'::uuid, 'period_start', '800', '1', 'fields-wd1-2026-09-26b-s009-rollback:d1720193-07a3-495c-ba7e-823426aa4f17:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''1'' restored on Quiahuiztlan', '[{"source": "https://sic.gob.mx/ficha.php?table=zona_arqueologica&table_id=112", "url": "https://sic.gob.mx/ficha.php?table=zona_arqueologica&table_id=112", "quote": "Cronología: 800 d. C. a época colonial.", "outcome": "found"}, {"source": "https://conoceveracruz.com/la-zona-arqueologica-quiahuiztlan-2/", "url": "https://conoceveracruz.com/la-zona-arqueologica-quiahuiztlan-2/", "quote": "Se cree que fue fundada entre los años 800 y 900 d.C. por grupos totonacas que buscaban protección.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0097)", "decision": "replace", "status": "MISSING", "reasoning": "The Secretaría de Cultura''s SIC entry gives the chronology as AD 800 to the colonial era and Conoce Veracruz dates the foundation to AD 800-900, in line with INAH''s Epiclassic start; that lies in the 500 - 1000 AD bucket, not the stored 1 - 500 AD one.", "value_page": null}]'::jsonb),
    ('d1720193-07a3-495c-ba7e-823426aa4f17'::uuid, 'site_type', 'City/town/settlement', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26b-s009-rollback:d1720193-07a3-495c-ba7e-823426aa4f17:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Necropolis/tombs complex'' restored on Quiahuiztlan', '[{"source": "https://lugares.inah.gob.mx/en/node/4450", "url": "https://lugares.inah.gob.mx/en/node/4450", "quote": "The settlement, on the slopes of the Cerro Bernal, nearly 20 miles north of Cempoala, is in the municipality of Actopan.", "outcome": "found"}, {"source": "https://es.wikipedia.org/wiki/Quiahuiztl%C3%A1n", "url": "https://es.wikipedia.org/wiki/Quiahuiztl%C3%A1n", "quote": "Fue ciudad con cerca de 16 mil habitantes", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0097)", "decision": "replace", "status": "CONFLICT", "reasoning": "INAH describes Quiahuiztlan as a settlement whose people lived in several zones with religious, civil and funerary buildings, and Wikipedia calls it a city of about 16,000 inhabitants that also held cemeteries and a fortress; the tombs are one part of the town, so City/town/settlement fits better than Necropolis/tombs complex.", "value_page": null}]'::jsonb),
    ('d1fb1d89-fc92-428f-9156-0b462f50569f'::uuid, 'period_name', '500 BC - 1 AD', '500 - 1000 AD', 'fields-wd1-2026-09-26b-s009-rollback:d1fb1d89-fc92-428f-9156-0b462f50569f:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''500 - 1000 AD'' restored on Gran Pajatén', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-200) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d1fb1d89-fc92-428f-9156-0b462f50569f'::uuid, 'period_start', '-200', '500', 'fields-wd1-2026-09-26b-s009-rollback:d1fb1d89-fc92-428f-9156-0b462f50569f:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''500'' restored on Gran Pajatén', '[{"source": "https://en.wikipedia.org/wiki/Gran_Pajat%C3%A9n", "url": "https://en.wikipedia.org/wiki/Gran_Pajat%C3%A9n", "quote": "Analysis of ceramic samples and radiocarbon dates show that the area was occupied as early as 200 BCE", "outcome": "found"}, {"source": "https://anthropology.iresearchnet.com/chachapoya-indians/", "url": "https://anthropology.iresearchnet.com/chachapoya-indians/", "quote": "Early radiocarbon dates from Gran Pajaten and Manachaqui Cave produced unassailable evidence that humans had occupied the montane cloud forests since 200 BC", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0019)", "decision": "replace", "status": "MISSING", "reasoning": "English Wikipedia states that ceramic samples and radiocarbon dates show Gran Pajaten was occupied as early as 200 BCE, and an encyclopedia entry on the Chachapoya independently says early radiocarbon dates from Gran Pajaten show occupation of the cloud forest since 200 BC; the first occupation therefore lies in the 500 BC - 1 AD bucket, not in 500-1000 AD (the visible Chachapoya and Inca-era buildings are a later phase).", "value_page": null}]'::jsonb),
    ('d1fd88e8-1e77-4bc2-859e-d72632d37500'::uuid, 'period_name', NULL, '1000 - 1500 AD', 'fields-wd1-2026-09-26b-s009-rollback:d1fd88e8-1e77-4bc2-859e-d72632d37500:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1000 - 1500 AD'' restored on Pukara, Vilcas Huamán', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d1fd88e8-1e77-4bc2-859e-d72632d37500'::uuid, 'period_start', NULL, '1000', 'fields-wd1-2026-09-26b-s009-rollback:d1fd88e8-1e77-4bc2-859e-d72632d37500:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''1000'' restored on Pukara, Vilcas Huamán', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0113)", "decision": "clear", "status": "MISSING", "reasoning": "The only description (MINCETUR inventory, copied on Turismo Peruano) assigns the site to the Chanka culture (''filiación Chanca'') without any year or century; no two sources date its start.", "value_page": null}]'::jsonb),
    ('d1fd88e8-1e77-4bc2-859e-d72632d37500'::uuid, 'site_type', 'Archaeological site', 'City/town/settlement', 'fields-wd1-2026-09-26b-s009-rollback:d1fd88e8-1e77-4bc2-859e-d72632d37500:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''City/town/settlement'' restored on Pukara, Vilcas Huamán', '[{"source": "https://en.wikipedia.org/wiki/Pukara,_Vilcas_Huam%C3%A1n", "url": "https://en.wikipedia.org/wiki/Pukara,_Vilcas_Huam%C3%A1n", "quote": "is an archaeological site in Peru located in the", "outcome": "found"}, {"source": "https://www.turismoperuano.com/sitio-arqueologico-de-pucara-ayacucho", "url": "https://www.turismoperuano.com/sitio-arqueologico-de-pucara-ayacucho", "quote": "Este sitio arqueológico es de filiación Chanca, está ubicado en la cima del cerro denominado Pucará, ubicado a 3,700 m.s.n.m., en la región puna", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0113)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia calls Pukara an archaeological site and the MINCETUR inventory an archaeological site of Chanka affiliation on the summit of Cerro Pucará with circular dwellings and chullpas (classed there under ''Templos''); no two sources describe it as a town or settlement, so the generic type is the one that holds.", "value_page": null}]'::jsonb),
    ('d2403f87-24a1-4f20-bb4c-ffd68ac59268'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s009-rollback:d2403f87-24a1-4f20-bb4c-ffd68ac59268:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1 - 500 AD'' restored on Intipanawin', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d2403f87-24a1-4f20-bb4c-ffd68ac59268'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s009-rollback:d2403f87-24a1-4f20-bb4c-ffd68ac59268:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''1'' restored on Intipanawin', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0110)", "decision": "clear", "status": "MISSING", "reasoning": "Neither the Wikipedia article nor the MINCETUR tourism inventory text dates the paintings or the burials at their base, and no other source was found. The stored value has no support, so the field is cleared.", "value_page": null}]'::jsonb),
    ('d281428b-8acc-438a-9056-7742575b7b8c'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s009-rollback:d281428b-8acc-438a-9056-7742575b7b8c:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1500 - 500 BC'' restored on Jabal al-Baidain', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d281428b-8acc-438a-9056-7742575b7b8c'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s009-rollback:d281428b-8acc-438a-9056-7742575b7b8c:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-1500'' restored on Jabal al-Baidain', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0121)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia and Sabq mention traces of ancient settlements, animal drawings and Thamudic inscriptions at Jabal al-Baidain but give no date for any of them. No source dates the start, so the stored -1500 is unsupported.", "value_page": null}]'::jsonb),
    ('d281428b-8acc-438a-9056-7742575b7b8c'::uuid, 'site_type', 'Archaeological site', 'Petroglyphs', 'fields-wd1-2026-09-26b-s009-rollback:d281428b-8acc-438a-9056-7742575b7b8c:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Petroglyphs'' restored on Jabal al-Baidain', '[{"source": "https://en.wikipedia.org/wiki/Jabal_al-Baidain", "url": "https://en.wikipedia.org/wiki/Jabal_al-Baidain", "quote": "Jabal al-Baidain is an archeological site representing a mountain located 13 km southwest of Dawadmi", "outcome": "found"}, {"source": "https://www.tagepedia.org/Entry.aspx?id=1027084&title=%D8%AC%D8%A8%D9%84_%D8%A7%D9%84%D8%A8%D9%8A%D8%B6%D8%AA%D9%8A%D9%86", "url": "https://www.tagepedia.org/Entry.aspx?id=1027084&title=%D8%AC%D8%A8%D9%84_%D8%A7%D9%84%D8%A8%D9%8A%D8%B6%D8%AA%D9%8A%D9%86", "quote": "جبل البيضتين يقع 13كم جنوب غرب الدوادمي، وعثر على آثار مستوطنات قديمة قرب قاعدته، كما تم الوقوف على نقوش حيوانية ومخربشات ثمودية رسمت على واجهة صخوره.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0022)", "decision": "replace", "status": "CONFLICT", "reasoning": "English Wikipedia calls Jabal al-Baidain an archaeological site (a mountain 13 km southwest of Dawadmi) and an Arabic encyclopedia entry drawn from the Saudi tourism and antiquities authority lists ancient settlement remains at its base plus animal engravings and Thamudic scribbles on its rock face; no readable English source uses the words rock art or petroglyph for this mountain, so the specific type cannot be quoted and the sourced type is Archaeological site.", "value_page": null}]'::jsonb),
    ('d2ecae04-608d-4755-9546-cf9ec07547af'::uuid, 'geom', 'SRID=4326;POINT(-7.018076 54.057253)', '0101000020E6100000373B60C32A331CC0F1DDC172CE0C4B40', 'fields-wd1-2026-09-26b-s009-rollback:d2ecae04-608d-4755-9546-cf9ec07547af:geom', 'rollback of fields-wd1-2026-09-26b-s009: geom ''0101000020E6100000373B60C32A331CC0F1DDC172CE0C4B40'' restored on Cohaw', '[{"source": "https://www.megalithic.co.uk/article.php?sid=6333450", "url": "https://www.megalithic.co.uk/article.php?sid=6333450", "quote": "Latitude: 54.057253N Longitude: 7.018076W", "outcome": "found"}, {"source": "https://www.megalithicireland.com/Cohaw%20Court%20Tomb.htm", "url": "https://www.megalithicireland.com/Cohaw%20Court%20Tomb.htm", "quote": "Longitude: 7° 1''5\" W Latitude: 54° 3'' 27\" N", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0013)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Megalithic Portal page for Cohaw Court Tomb (Co. Cavan, nearest town Cootehill) gives 54.057253N 7.018076W and megalithicireland.com''s Cohaw Court Tomb page gives 54° 3'' 27\" N, 7° 1''5\" W (the same spot within about 30 m); the stored point (54.1000, -7.0500), which copies the English Wikipedia''s rounded 54.100°N 7.050°W, lies about 5.3 km north-north-west of the tomb, so the point is replaced.", "value_page": null}]'::jsonb),
