    ('d2ecae04-608d-4755-9546-cf9ec07547af'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s009-rollback:d2ecae04-608d-4755-9546-cf9ec07547af:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''4500 - 3000 BC'' restored on Cohaw', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d2ecae04-608d-4755-9546-cf9ec07547af'::uuid, 'period_start', NULL, '-4000', 'fields-wd1-2026-09-26b-s009-rollback:d2ecae04-608d-4755-9546-cf9ec07547af:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-4000'' restored on Cohaw', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0082)", "decision": "clear", "status": "MISSING", "reasoning": "The pages about the Cohaw tomb (Wikipedia, Heritage Ireland, Megalithic Portal, megalithicireland.com, IrishHistory.com) call it Neolithic but give no year, century or millennium; the one dated listing found (This is Cavan, ''c. 2000 BC'') is unsupported and contradicts the Neolithic dating, so no two independent sources date its start.", "value_page": null}]'::jsonb),
    ('d34a4c75-f3e7-42e8-accb-1e2329dc27fa'::uuid, 'site_type', 'Fortification', 'City/town/settlement', 'fields-wd1-2026-09-26b-s009-rollback:d34a4c75-f3e7-42e8-accb-1e2329dc27fa:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''City/town/settlement'' restored on Stanwick Iron Age Fortifications', '[{"source": "https://en.wikipedia.org/wiki/Stanwick_Iron_Age_Fortifications", "url": "https://en.wikipedia.org/wiki/Stanwick_Iron_Age_Fortifications", "quote": "They maintained that the six miles (10 km) fortification was too long to be easily defended", "outcome": "found"}, {"source": "https://www.english-heritage.org.uk/visit/places/stanwick-iron-age-fortifications/history/", "url": "https://www.english-heritage.org.uk/visit/places/stanwick-iron-age-fortifications/history/", "quote": "The features now visible at Stanwick are the excavated remains of only a small part of an Iron Age rampart and ditch that encloses an area of 310 hectares (766 acres) and is nearly 6.5 kilometres (4 miles) long.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0046)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe the site as a vast Iron Age circuit of ramparts and ditches (a hill fort/oppidum enclosure), i.e. a fortification, not a town; the stored City/town/settlement is replaced by Fortification.", "value_page": null}]'::jsonb),
    ('d3789a45-3747-4bae-8b9e-88f359f5561d'::uuid, 'site_type', 'Stone circle', 'Megalithic stones', 'fields-wd1-2026-09-26b-s009-rollback:d3789a45-3747-4bae-8b9e-88f359f5561d:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Megalithic stones'' restored on Stone Circles at Odry', '[{"source": "https://web.astronomicalheritage.net/index.php/show-entity?identity=8&idsubentity=1", "url": "https://web.astronomicalheritage.net/index.php/show-entity?identity=8&idsubentity=1", "quote": "It contains the greatest concentration of stone circles in Poland", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=14798", "url": "https://www.megalithic.co.uk/article.php?sid=14798", "quote": "Type: Stone Circle", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0116)", "decision": "replace", "status": "MISSING", "reasoning": "The UNESCO astronomical heritage portal and the Megalithic Portal describe the site as a group of stone circles (10 complete and 2 damaged circles within a Wielbark culture cemetery). ''Stone circle'' is more specific than the stored ''Megalithic stones''.", "value_page": null}]'::jsonb),
    ('d3789a45-3747-4bae-8b9e-88f359f5561d'::uuid, 'source_url', 'https://pl.wikipedia.org/wiki/Odry_(cmentarzysko)', 'https://www3.astronomicalheritage.net/index.php/show-entity?identity=8&idsubentity=1#:~:text=The%20%E2%80%9CStone%20Circles%20at%20Odry,of%20the%20early%2020th%20century.', 'fields-wd1-2026-09-26b-s009-rollback:d3789a45-3747-4bae-8b9e-88f359f5561d:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://www3.astronomicalheritage.net/index.php/show-entity?identity=8&idsubentity=1#:~:text=The%20%E2%80%9CStone%20Circles%20at%20Odry,of%20the%20early%2020th%20century.'' restored on Stone Circles at Odry', '[{"source": "https://pl.wikipedia.org/wiki/Odry_(cmentarzysko)", "url": "https://pl.wikipedia.org/wiki/Odry_(cmentarzysko)", "quote": "Cmentarzysko w Odrach – stanowisko archeologiczne kultury wielbarskiej wiązane z osiedleniem Gotów i Gepidów w pierwszych wiekach n.e.", "outcome": "found"}, {"source": "https://web.astronomicalheritage.net/index.php/show-entity?identity=8&idsubentity=1", "url": "https://web.astronomicalheritage.net/index.php/show-entity?identity=8&idsubentity=1", "quote": "The “Stone Circles at Odry” Archaeological and Natural Reserve is located on the right bank of the Wda River and extends over an area of 16 ha.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0116)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is a text-fragment link on the UNESCO portal. The site has its own Wikipedia article, the Polish article on the Odry cemetery with its stone circles, which is preferred; the UNESCO portal describes the same reserve on the Wda.", "value_page": {"lang": "pl", "problem": null, "resolved_title": "Odry (cmentarzysko)", "unreadable": false, "wikibase_item": "Q11796318"}}]'::jsonb),
    ('d3a35b0d-cf76-4286-8cd4-2f53e52556ad'::uuid, 'period_name', '500 BC - 1 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s009-rollback:d3a35b0d-cf76-4286-8cd4-2f53e52556ad:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1500 - 500 BC'' restored on Porta Nord Acropoli', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-409) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d3a35b0d-cf76-4286-8cd4-2f53e52556ad'::uuid, 'period_start', '-409', '-1500', 'fields-wd1-2026-09-26b-s009-rollback:d3a35b0d-cf76-4286-8cd4-2f53e52556ad:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-1500'' restored on Porta Nord Acropoli', '[{"source": "https://en.wikipedia.org/wiki/Selinunte", "url": "https://en.wikipedia.org/wiki/Selinunte", "quote": "Only a small part of the fortifications belong to the old city – they are mostly from Hermocrates'' reconstruction and successive repairs in the fourth and third centuries. The fact that architectural elements were recycled into it demonstrates that some of the temples were already abandoned in 409 BC.", "outcome": "found"}, {"source": "https://www.worldhistory.org/Selinus/", "url": "https://www.worldhistory.org/Selinus/", "quote": "The original 6th century BCE acropolis was fortified, but the walls visible at the site today date to the 5th to 3rd centuries BCE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0087)", "decision": "replace", "status": "MISSING", "reasoning": "English Wikipedia says the acropolis''s northern fortifications, with the gate and its three towers, are mostly Hermocrates'' reconstruction after the destruction of 409 BC, and World History Encyclopedia dates the visible walls, including the three-towered North Gate, to the 5th to 3rd centuries BCE; the start therefore lies in 500 BC - 1 AD, not in the stored bucket.", "value_page": null}]'::jsonb),
    ('d3a35b0d-cf76-4286-8cd4-2f53e52556ad'::uuid, 'site_type', 'Gate', 'Temple complex', 'fields-wd1-2026-09-26b-s009-rollback:d3a35b0d-cf76-4286-8cd4-2f53e52556ad:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Temple complex'' restored on Porta Nord Acropoli', '[{"source": "https://www.worldhistory.org/Selinus/", "url": "https://www.worldhistory.org/Selinus/", "quote": "The fortifications include regular-shaped towers and the impressive three-towered North Gate with its preceding street of shops.", "outcome": "found"}, {"source": "https://www.robertvandermeer.nl/Selinunte/Northern_Defences_Selinus.html", "url": "https://www.robertvandermeer.nl/Selinunte/Northern_Defences_Selinus.html", "quote": "The Northern Gate, one of the main gates of the city, is well preserved.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0087)", "decision": "replace", "status": "CONFLICT", "reasoning": "World History Encyclopedia and Robert van der Meer''s page on Selinunte''s northern defences both describe the site as the North Gate of the acropolis fortifications, a city gate, not a temple complex.", "value_page": null}]'::jsonb),
    ('d3a35b0d-cf76-4286-8cd4-2f53e52556ad'::uuid, 'source_url', 'https://www.selinunte.net/le_fortificazioni.htm', 'https://en.wikipedia.org/wiki/Selinunte', 'fields-wd1-2026-09-26b-s009-rollback:d3a35b0d-cf76-4286-8cd4-2f53e52556ad:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Selinunte'' restored on Porta Nord Acropoli', '[{"source": "https://www.selinunte.net/le_fortificazioni.htm", "url": "https://www.selinunte.net/le_fortificazioni.htm", "quote": "Al limite nord dell''acropoli, sull''asse della plateia nord-sud, venne aperta una porta (Porta Nord)", "outcome": "found"}, {"source": "https://www.worldhistory.org/Selinus/", "url": "https://www.worldhistory.org/Selinus/", "quote": "The fortifications include regular-shaped towers and the impressive three-towered North Gate with its preceding street of shops.", "outcome": "found"}, {"source": "WD1 decision (counted, round 2, wd1-r2-b0003)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is the whole town of Selinunte, not this gate; the site is the Porta Nord (North Gate) at the northern limit of the Selinunte acropolis, which has no Wikipedia article of its own (Wikidata Q140891419 has no sitelinks). The Selinunte.net page on the fortifications describes this gate and its defensive system in a dedicated passage, and the World History Encyclopedia independently describes the three-towered North Gate of the acropolis fortifications, so the fortifications page replaces the town article.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('d3dde28f-ad70-41ce-b5b4-6bb943aebbee'::uuid, 'period_name', '3000 - 1500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s009-rollback:d3dde28f-ad70-41ce-b5b4-6bb943aebbee:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''4500 - 3000 BC'' restored on Nether Largie Mid Cairn, Kilmartin Glen', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-2000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d3dde28f-ad70-41ce-b5b4-6bb943aebbee'::uuid, 'period_start', '-2000', '-4000', 'fields-wd1-2026-09-26b-s009-rollback:d3dde28f-ad70-41ce-b5b4-6bb943aebbee:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-4000'' restored on Nether Largie Mid Cairn, Kilmartin Glen', '[{"source": "https://www.pilgrimmap.com/site/nether-largie-mid-cairn", "url": "https://www.pilgrimmap.com/site/nether-largie-mid-cairn", "quote": "Nether Largie Mid Cairn was constructed as a burial monument for a high-status individual during the Bronze Age, around 2000 BCE.", "outcome": "found"}, {"source": "https://portal.historicenvironment.scot/apex/f?p=1505:300:::::VIEWTYPE,VIEWREF:designation,SM13298", "url": "https://portal.historicenvironment.scot/apex/f?p=1505:300:::::VIEWTYPE,VIEWREF:designation,SM13298", "quote": "The monument is a round burial cairn covering a cist of the Bronze Age, built sometime between 2500 and 1000 BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0022)", "decision": "replace", "status": "MISSING", "reasoning": "Nether Largie Mid Cairn is a Bronze Age cist cairn, not the Neolithic Kilmartin Glen area the stored -4000 came from: Historic Environment Scotland''s scheduling text dates it to the Bronze Age, built sometime between 2500 and 1000 BC, and a second site gives around 2000 BCE, so the start is c. 2000 BC, in the 3000 - 1500 BC bucket.", "value_page": null}]'::jsonb),
    ('d3dde28f-ad70-41ce-b5b4-6bb943aebbee'::uuid, 'source_url', 'https://www.historicenvironment.scot/visit/all/kilmartin-glen-nether-largie-mid-cairn/', 'https://en.wikipedia.org/wiki/Kilmartin_Glen', 'fields-wd1-2026-09-26b-s009-rollback:d3dde28f-ad70-41ce-b5b4-6bb943aebbee:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Kilmartin_Glen'' restored on Nether Largie Mid Cairn, Kilmartin Glen', '[{"source": "https://www.historicenvironment.scot/visit/all/kilmartin-glen-nether-largie-mid-cairn/", "url": "https://www.historicenvironment.scot/visit/all/kilmartin-glen-nether-largie-mid-cairn/", "quote": "Nether Largie Mid Cairn stands at the heart of a 2km line of cairns in Kilmartin Glen.", "outcome": "found"}, {"source": "https://www.stonepages.com/scotland/netherlargiec.html", "url": "https://www.stonepages.com/scotland/netherlargiec.html", "quote": "The Nether Largie Mid cairn dates from the Early Bronze Age; two stone cists are visible", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0022)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the English Wikipedia article on the whole Kilmartin Glen area, which has no page of its own for this cairn; the Historic Environment Scotland visitor page is devoted to Nether Largie Mid Cairn and Stone Pages independently describes the same cairn.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('d49017eb-8e45-45af-a6d4-f90f3d35f3e3'::uuid, 'site_type', 'City', 'City/town/settlement', 'fields-wd1-2026-09-26b-s009-rollback:d49017eb-8e45-45af-a6d4-f90f3d35f3e3:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''City/town/settlement'' restored on Camulodunum', '[{"source": "https://en.wikipedia.org/wiki/Camulodunum", "url": "https://en.wikipedia.org/wiki/Camulodunum", "quote": "castrum and city in Roman Britain, and the first capital of the province.", "outcome": "found"}, {"source": "https://www.roman-britain.co.uk/places/camulodunum/", "url": "https://www.roman-britain.co.uk/places/camulodunum/", "quote": "The probable Civitate for the Trinovantes, the city was sacked in the Boudabrican revolt and the inhabitants massacred.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0030)", "decision": "replace", "status": "CONFLICT", "reasoning": "The legionary fortress stood only in the 40s AD; both Wikipedia and Roman-Britain.co.uk describe Camulodunum as a Roman city (the colonia and first provincial capital), so the most specific fitting type is City, not a fort type.", "value_page": null}]'::jsonb),
