    ('d53238e1-cad3-4f42-bfb0-bf072e4aebd3'::uuid, 'period_start', '-751', '-500', 'fields-wd1-2026-09-26b-s009-rollback:d53238e1-cad3-4f42-bfb0-bf072e4aebd3:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-500'' restored on Nubian Pyramids', '[{"source": "https://en.wikipedia.org/wiki/Nubian_pyramids", "url": "https://en.wikipedia.org/wiki/Nubian_pyramids", "quote": "The earliest pyramids in El Kurru were constructed in 751 BC", "outcome": "found"}, {"source": "https://www.outlooktraveller.com/destinations/international/inside-sudans-nubian-pyramids-exploring-the-ancient-cities-of-mero%C3%AB-nuri-and-el-kurru", "url": "https://www.outlooktraveller.com/destinations/international/inside-sudans-nubian-pyramids-exploring-the-ancient-cities-of-mero%C3%AB-nuri-and-el-kurru", "quote": "The pyramids were constructed by the kings, queens and nobles of the ancient Kingdom of Kush between roughly the 8th century BCE and the 4th century CE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0136)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia dates the earliest Nubian pyramids, at El-Kurru, to 751 BC and Outlook Traveller dates the building of Sudan''s Nubian pyramids from roughly the 8th century BC; the start therefore lies in the 1500-500 BC bucket, not the stored 500 BC - 1 AD one.", "value_page": null}]'::jsonb),
    ('d55baca6-8a56-4a3b-8323-f5399e331666'::uuid, 'site_type', 'Gate', 'Gate/archway/bridge', 'fields-wd1-2026-09-26b-s009-rollback:d55baca6-8a56-4a3b-8323-f5399e331666:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Gate/archway/bridge'' restored on Eastern Gate of Philippopolis', '[{"source": "https://en.wikipedia.org/wiki/Eastern_gate_of_Philippopolis", "url": "https://en.wikipedia.org/wiki/Eastern_gate_of_Philippopolis", "quote": "The Eastern gate of Philippopolis is one of the three known entrances to the ancient", "outcome": "found"}, {"source": "https://oldplovdiv.bg/en/sights/16", "url": "https://oldplovdiv.bg/en/sights/16", "quote": "The Eastern Gate of Philippopolis was built in the 2nd century.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0013)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both English Wikipedia and Old Plovdiv describe the site as the eastern city gate of Philippopolis, one of its entrances in the Roman walls. ''Gate'' is the most specific canonical type and is narrower than the stored ''Gate/archway/bridge''. Wikidata''s ''quarter'' is wrong.", "value_page": null}]'::jsonb),
    ('d5a5f6ff-a9cd-424e-9af9-572b0844f980'::uuid, 'period_name', '1500 - 500 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s009-rollback:d5a5f6ff-a9cd-424e-9af9-572b0844f980:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''3000 - 1500 BC'' restored on Timpone della Motta', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1500) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d5a5f6ff-a9cd-424e-9af9-572b0844f980'::uuid, 'period_start', '-1500', '-3000', 'fields-wd1-2026-09-26b-s009-rollback:d5a5f6ff-a9cd-424e-9af9-572b0844f980:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-3000'' restored on Timpone della Motta', '[{"source": "https://parcoarcheologicofrancavillamarittima.it/contenuti/2309395/sito", "url": "https://parcoarcheologicofrancavillamarittima.it/contenuti/2309395/sito", "quote": "Gli studi condotti sino a ora hanno dimostrato che l’area risulta abitata sin dalla media età del bronzo (secoli XV-XIV a.C.)", "outcome": "found"}, {"source": "https://www.calabriatours.org/heritage/sito-archeologico-di-francavilla-marittima.html", "url": "https://www.calabriatours.org/heritage/sito-archeologico-di-francavilla-marittima.html", "quote": "L''antico villaggio è stato individuato in località Timpone della Motta, da cui è emersa una frequentazione del sito sin dall''epoca del Bronzo tra il XIII e il X secolo a.C.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0089)", "decision": "replace", "status": "MISSING", "reasoning": "The official site of the archaeological park dates the first habitation of the hill to the Middle Bronze Age, 15th-14th centuries BC (English Wikipedia: inhabited since the Middle Bronze Age); a second source dates Bronze Age occupation to the 13th-10th century BC. Both lie in the 1500 - 500 BC bucket, not the stored 3000 - 1500 BC one.", "value_page": null}]'::jsonb),
    ('d5a5f6ff-a9cd-424e-9af9-572b0844f980'::uuid, 'site_type', 'Sanctuary', 'City/town/settlement', 'fields-wd1-2026-09-26b-s009-rollback:d5a5f6ff-a9cd-424e-9af9-572b0844f980:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''City/town/settlement'' restored on Timpone della Motta', '[{"source": "https://en.wikipedia.org/wiki/Timpone_della_Motta", "url": "https://en.wikipedia.org/wiki/Timpone_della_Motta", "quote": "Close to the hilltop is the acropolis, which was the location of a sanctuary with three temples.", "outcome": "found"}, {"source": "https://parchicrotonesibari.it/en/section/il-santuario-di-timpone-motta-a-francavilla-marittima-una-finestra-sul-passato-di-sibari", "url": "https://parchicrotonesibari.it/en/section/il-santuario-di-timpone-motta-a-francavilla-marittima-una-finestra-sul-passato-di-sibari", "quote": "The sanctuary of Timpone Motta thus represents not only one of the most important religious centers of Magna Graecia", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0089)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is an Oenotrian settlement that became the Sybarite sanctuary of Athena with the earliest Greek temples of Italy; its remains and significance are those of the sanctuary, which both Wikipedia and the state archaeological parks of Crotone and Sibari describe.", "value_page": null}]'::jsonb),
