    ('d5c4fc5c-f8ad-4b97-b2fd-087311f733c8'::uuid, 'period_name', '500 BC - 1 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s009-rollback:d5c4fc5c-f8ad-4b97-b2fd-087311f733c8:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1 - 500 AD'' restored on Feddersen Wierde', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-100) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d5c4fc5c-f8ad-4b97-b2fd-087311f733c8'::uuid, 'period_start', '-100', '1', 'fields-wd1-2026-09-26b-s009-rollback:d5c4fc5c-f8ad-4b97-b2fd-087311f733c8:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''1'' restored on Feddersen Wierde', '[{"source": "https://nihk.de/en/research/completed-projects/feddersen-wierde", "url": "https://nihk.de/en/research/completed-projects/feddersen-wierde", "quote": "The results demonstrate that the Wurt had been established as a low-lying settlement in the 1st century BC", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Feddersen_Wierde", "url": "https://de.wikipedia.org/wiki/Feddersen_Wierde", "quote": "Er war vom 1. Jahrhundert v. Chr. bis ins 5. Jahrhundert von Altsachsen bewohnt", "outcome": "found"}, {"source": "https://www.burg-bederkesa.de/archaeologie-im-museum/feddersen-wierde/", "url": "https://www.burg-bederkesa.de/archaeologie-im-museum/feddersen-wierde/", "quote": "Auf ihm errichteten im 1. Jh. v. Chr. während einer neuen Rückzugsphase des Meeres mehrere Siedlergruppen ihre Wohnplätze zu ebener Erde.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0057)", "decision": "replace", "status": "MISSING", "reasoning": "The excavating institute (NIhK), the German Wikipedia and the Burg Bederkesa museum all date the foundation of the settlement to the 1st century BC, so the start is -100 (bucket 500 BC - 1 AD), not the stored AD 1.", "value_page": null}]'::jsonb),
    ('d5c4fc5c-f8ad-4b97-b2fd-087311f733c8'::uuid, 'site_type', 'Village', 'City/town/settlement', 'fields-wd1-2026-09-26b-s009-rollback:d5c4fc5c-f8ad-4b97-b2fd-087311f733c8:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''City/town/settlement'' restored on Feddersen Wierde', '[{"source": "https://nihk.de/en/research/completed-projects/feddersen-wierde", "url": "https://nihk.de/en/research/completed-projects/feddersen-wierde", "quote": "Not only does the Feddersen Wierde represent the first, and to this day the only time that a large village Wurt mound on the southern North Sea coast had been excavated almost in its entirety", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Feddersen_Wierde", "url": "https://de.wikipedia.org/wiki/Feddersen_Wierde", "quote": "Die Dorfwurt Feddersen-Wierde war ein frühgeschichtliches Wurtendorf in der Seemarsch des Landes Wursten im Landkreis Cuxhaven", "outcome": "found"}, {"source": "https://m-v-m.de/projekte/wegmarken/wegmarke-die-feddersen-wierde/", "url": "https://m-v-m.de/projekte/wegmarken/wegmarke-die-feddersen-wierde/", "quote": "In dem erhöhten Gelände hinter dieser Tafel lag ein eisenzeitliches Wurtendorf.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0057)", "decision": "replace", "status": "MISSING", "reasoning": "The NIhK calls it a large village wurt, the German Wikipedia and the local society''s marker a wurt village (Wurtendorf) of about 26 farmsteads; Village is more specific than the composite City/town/settlement, and it was never a town.", "value_page": null}]'::jsonb),
    ('d60110a3-f57d-4fd1-afaf-05740fdef6a6'::uuid, 'site_type', 'Theatre', 'Megalithic stones', 'fields-wd1-2026-09-26b-s009-rollback:d60110a3-f57d-4fd1-afaf-05740fdef6a6:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Megalithic stones'' restored on Théâtre Romain Khmissa (Ancient Thubursicum, Roman Theatre)', '[{"source": "https://followinghadrianphotography.com/2025/06/02/thubursicum-numidarum-khemissa/", "url": "https://followinghadrianphotography.com/2025/06/02/thubursicum-numidarum-khemissa/", "quote": "The Roman theatre of Thubursicum is considered one of the most beautiful and best-preserved ancient theatres in North Africa.", "outcome": "found"}, {"source": "https://theatrum.de/thubursicumnumidarum.html", "url": "https://theatrum.de/thubursicumnumidarum.html", "quote": "Das römische Theater ist an einen natürlichen Hang gebaut worden.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the Roman theatre of Thubursicum Numidarum at Khamissa (Wikidata: Roman theatre); Following Hadrian and theatrum.de both describe it as a Roman theatre (cavea, orchestra, pulpitum, scaenae frons). Nothing about it is megalithic.", "value_page": null}]'::jsonb),
    ('d60110a3-f57d-4fd1-afaf-05740fdef6a6'::uuid, 'source_url', 'https://theatrum.de/thubursicumnumidarum.html', 'https://en.wikipedia.org/wiki/Thubursicum', 'fields-wd1-2026-09-26b-s009-rollback:d60110a3-f57d-4fd1-afaf-05740fdef6a6:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Thubursicum'' restored on Théâtre Romain Khmissa (Ancient Thubursicum, Roman Theatre)', '[{"source": "https://theatrum.de/thubursicumnumidarum.html", "url": "https://theatrum.de/thubursicumnumidarum.html", "quote": "Thubursicum Numidarum (Khamissa), Grundriss des römischen Theaters (nach Fiechter).", "outcome": "found"}, {"source": "https://tahwissa.app/en/place/souk-ahras/theatre-romain-khmissa-t10445", "url": "https://tahwissa.app/en/place/souk-ahras/theatre-romain-khmissa-t10445", "quote": "Théâtre Romain Khmissa By tahwissa webmaster 2", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about the whole town site of Thubursicum, not the theatre, and the theatre has no Wikipedia article of its own (its Wikidata item Q2429753 has no sitelinks). The theatrum.de page, which Wikidata links through its Theatrum ID, is devoted to this theatre at Khamissa (plan, measurements, description, literature), and the Tahwissa heritage guide names the same Théâtre Romain Khmissa.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('d621bf90-9c67-405d-b7fc-d8efb7057f0b'::uuid, 'geom', 'SRID=4326;POINT(102.356278 17.731056)', '0101000020E610000025F0DDB1CF9759407238D6FC71B73140', 'fields-wd1-2026-09-26b-s009-rollback:d621bf90-9c67-405d-b7fc-d8efb7057f0b:geom', 'rollback of fields-wd1-2026-09-26b-s009: geom ''0101000020E610000025F0DDB1CF9759407238D6FC71B73140'' restored on Phu Phra Bat Historical Park', '[{"source": "https://en.wikipedia.org/wiki/Phu_Phra_Bat_Historical_Park", "url": "https://en.wikipedia.org/wiki/Phu_Phra_Bat_Historical_Park", "quote": "17°43′51.8″N 102°21′22.6″E", "outcome": "found"}, {"source": "https://www.unescotracker.net/Sites/Detail/1062", "url": "https://www.unescotracker.net/Sites/Detail/1062", "quote": "17.7311°, 102.3563°", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0139)", "decision": "replace", "status": "CONFLICT", "reasoning": "English Wikipedia and the UNESCO Heritage Tracker entry for the World Heritage property Phu Phrabat both place the historical park at 17.7311, 102.3563 (OpenStreetMap''s node for the park, shown by Mapcarta, is at 17.73142, 102.35385); the stored point is 2.3 km to the south-east of the park, so it is replaced.", "value_page": null}]'::jsonb),
