    ('d621bf90-9c67-405d-b7fc-d8efb7057f0b'::uuid, 'lon', '102.356278', '102.37205168412818', 'fields-wd1-2026-09-26b-s009-rollback:d621bf90-9c67-405d-b7fc-d8efb7057f0b:lon', 'rollback of fields-wd1-2026-09-26b-s009: lon ''102.37205168412818'' restored on Phu Phra Bat Historical Park', '[{"source": "https://en.wikipedia.org/wiki/Phu_Phra_Bat_Historical_Park", "url": "https://en.wikipedia.org/wiki/Phu_Phra_Bat_Historical_Park", "quote": "17°43′51.8″N 102°21′22.6″E", "outcome": "found"}, {"source": "https://www.unescotracker.net/Sites/Detail/1062", "url": "https://www.unescotracker.net/Sites/Detail/1062", "quote": "17.7311°, 102.3563°", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0139)", "decision": "replace", "status": "CONFLICT", "reasoning": "English Wikipedia and the UNESCO Heritage Tracker entry for the World Heritage property Phu Phrabat both place the historical park at 17.7311, 102.3563 (OpenStreetMap''s node for the park, shown by Mapcarta, is at 17.73142, 102.35385); the stored point is 2.3 km to the south-east of the park, so it is replaced.", "value_page": null}]'::jsonb),
    ('d621bf90-9c67-405d-b7fc-d8efb7057f0b'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s009-rollback:d621bf90-9c67-405d-b7fc-d8efb7057f0b:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''4500 - 3000 BC'' restored on Phu Phra Bat Historical Park', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d621bf90-9c67-405d-b7fc-d8efb7057f0b'::uuid, 'period_start', NULL, '-4500', 'fields-wd1-2026-09-26b-s009-rollback:d621bf90-9c67-405d-b7fc-d8efb7057f0b:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-4500'' restored on Phu Phra Bat Historical Park', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0139)", "decision": "clear", "status": "MISSING", "reasoning": "Sources disagree on when the site''s history begins: the ICOMOS evaluation dates the earliest occupation to the 1st century BCE, the Fine Arts Department to 2,500-3,000 years ago, and popular pages to 6,000 years ago or 4000-2500 BC. No two independent sources date the start into the same bucket in a readable form, so the field is cleared.", "value_page": null}]'::jsonb),
    ('d661105f-26e9-4cea-b868-20c58ee3c52c'::uuid, 'site_type', 'Heritage site', 'Temple complex', 'fields-wd1-2026-09-26b-s009-rollback:d661105f-26e9-4cea-b868-20c58ee3c52c:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Temple complex'' restored on Gyeongju Historic Areas', '[{"source": "https://en.wikipedia.org/wiki/Gyeongju_Historic_Areas", "url": "https://en.wikipedia.org/wiki/Gyeongju_Historic_Areas", "quote": "is a World Heritage Site in Gyeongju", "outcome": "found"}, {"source": "https://unescoworld.com/heritage/gyeongju-historic-areas/", "url": "https://unescoworld.com/heritage/gyeongju-historic-areas/", "quote": "The Gyeongju Historic Areas contain a remarkable concentration of outstanding examples of Korean Buddhist art, in the form of sculptures, reliefs, pagodas, and the remains of temples and palaces", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0127)", "decision": "replace", "status": "MISSING", "reasoning": "The property is a World Heritage ensemble of five belts: Namsan''s temple ruins and statuary, the Wolseong palace, the royal tumuli, the Hwangnyongsa temple and mountain fortresses. UNESCO describes sculptures, pagodas and the remains of temples and palaces. No single specific type such as Temple complex holds for the whole, so the generic Heritage site fits.", "value_page": null}]'::jsonb),
    ('d66ae4dc-8aaa-4934-b332-5d8eda991bc8'::uuid, 'site_type', 'Fortress', 'City/town/settlement', 'fields-wd1-2026-09-26b-s009-rollback:d66ae4dc-8aaa-4934-b332-5d8eda991bc8:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''City/town/settlement'' restored on Kovachevsko kale', '[{"source": "https://archaeologyinbulgaria.com/kovachevsko-kale-fortress-popovo-bulgaria/", "url": "https://archaeologyinbulgaria.com/kovachevsko-kale-fortress-popovo-bulgaria/", "quote": "The Kovachevsko Kale Fortress is a Late Antiquity and Late Roman fortress located 6 km west of the town of Popovo, Targovishte District, in Northeast Bulgaria.", "outcome": "found"}, {"source": "https://bg.wikipedia.org/wiki/%D0%9A%D0%BE%D0%B2%D0%B0%D1%87%D0%B5%D0%B2%D1%81%D0%BA%D0%BE_%D0%BA%D0%B0%D0%BB%D0%B5", "url": "https://bg.wikipedia.org/wiki/%D0%9A%D0%BE%D0%B2%D0%B0%D1%87%D0%B5%D0%B2%D1%81%D0%BA%D0%BE_%D0%BA%D0%B0%D0%BB%D0%B5", "quote": "Ковачевското кале е късноримската крепост, която се намира на 6 км западно от гр. Попово", "outcome": "found"}, {"source": "https://opoznai.bg/view/kasnoantichnata-rimska-krepost-kovachevsko-kale", "url": "https://opoznai.bg/view/kasnoantichnata-rimska-krepost-kovachevsko-kale", "quote": "Късноантичната римска крепост \"Ковачевско кале\"", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0014)", "decision": "replace", "status": "CONFLICT", "reasoning": "Archaeology in Bulgaria, Bulgarian Wikipedia and Opoznai.bg all describe Kovachevsko kale as a Late Roman fortress (krepost) with 3.2 m walls and 17 towers; the name itself means fortress, so Fortress fits better than the generic settlement type.", "value_page": null}]'::jsonb),
    ('d686e433-d062-4546-818f-1df39fce0931'::uuid, 'period_name', '1500 - 500 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s009-rollback:d686e433-d062-4546-818f-1df39fce0931:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''3000 - 1500 BC'' restored on Flag Fen', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1365) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d686e433-d062-4546-818f-1df39fce0931'::uuid, 'period_start', '-1365', '-3000', 'fields-wd1-2026-09-26b-s009-rollback:d686e433-d062-4546-818f-1df39fce0931:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-3000'' restored on Flag Fen', '[{"source": "https://en.wikipedia.org/wiki/Flag_Fen", "url": "https://en.wikipedia.org/wiki/Flag_Fen", "quote": "Dendrochronological analysis (dating of the posts by studying tree rings) led to an estimated date for the various stages of construction of between 1365 and 967 BC.", "outcome": "found"}, {"source": "https://peterborougharchaeology.org/peterborough-archaeological-sites/flag-fen/", "url": "https://peterborougharchaeology.org/peterborough-archaeological-sites/flag-fen/", "quote": "It was constructed between 900 and 1400BC and comprised more than 60,000 upright timbers and 250,000 horizontal planks.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0034)", "decision": "replace", "status": "MISSING", "reasoning": "Tree-ring dates put the start of the causeway and platform at 1365 BC (Wikipedia), and Peterborough Archaeology dates its construction to between 1400 and 900 BC with the first double post row around 1300 BC; the start lies in 1500 - 500 BC, not in the stored 3000 - 1500 BC bucket.", "value_page": null}]'::jsonb),
    ('d6ca1bdf-173c-4659-b1fc-c9fb7259c5a3'::uuid, 'period_name', '1500 - 500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s009-rollback:d6ca1bdf-173c-4659-b1fc-c9fb7259c5a3:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''500 BC - 1 AD'' restored on Ham Hill, Somerset', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-800) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d6ca1bdf-173c-4659-b1fc-c9fb7259c5a3'::uuid, 'period_start', '-800', '-500', 'fields-wd1-2026-09-26b-s009-rollback:d6ca1bdf-173c-4659-b1fc-c9fb7259c5a3:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-500'' restored on Ham Hill, Somerset', '[{"source": "https://api.repository.cam.ac.uk/server/api/core/bitstreams/5ca4188b-071e-4971-b4d6-6f374e563c5c/content", "url": "https://api.repository.cam.ac.uk/server/api/core/bitstreams/5ca4188b-071e-4971-b4d6-6f374e563c5c/content", "quote": "sealed by the later ramparts also returned dates of c. 800BC.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Ham_Hill_Hillfort", "url": "https://en.wikipedia.org/wiki/Ham_Hill_Hillfort", "quote": "Archaeological finds, which date the original occupation to the 7th century BC", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0006)", "decision": "replace", "status": "MISSING", "reasoning": "The stored -500 is too late for the Ham Hill hillfort (Stoke-sub-Hamdon, Somerset). The Cambridge Archaeological Unit and Cardiff University post-excavation assessment reports radiocarbon dates of c. 800 BC for the pre-rampart enclosing ditches sealed by the later ramparts (the earliest hillfort enclosure), and Wikipedia''s Ham Hill Hillfort article dates the original occupation to the 7th century BC, so the site starts in the 1500 - 500 BC bucket, about 800 BC.", "value_page": null}]'::jsonb),
    ('d6ca1bdf-173c-4659-b1fc-c9fb7259c5a3'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s009-rollback:d6ca1bdf-173c-4659-b1fc-c9fb7259c5a3:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Fortress/citadel'' restored on Ham Hill, Somerset', '[{"source": "https://en.wikipedia.org/wiki/Ham_Hill,_Somerset", "url": "https://en.wikipedia.org/wiki/Ham_Hill,_Somerset", "quote": "Ham Hill is the site of a very large Bronze Age and Iron Age hill fort of the Durotriges tribe", "outcome": "found"}, {"source": "https://www.wessexarch.co.uk/our-work/ham-hill-iron-age-hillfort", "url": "https://www.wessexarch.co.uk/our-work/ham-hill-iron-age-hillfort", "quote": "Wessex Archaeology has recently carried out archaeological excavation inside one of the largest Iron Age hillforts in Britain.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0006)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia calls Ham Hill a very large Bronze Age and Iron Age hill fort and Wessex Archaeology describes its excavation at Ham Hill as inside one of the largest Iron Age hillforts in Britain; neither calls it a fortress or citadel, so the type is Fort, not the hill it stands on.", "value_page": null}]'::jsonb),
    ('d6ca1bdf-173c-4659-b1fc-c9fb7259c5a3'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Ham_Hill_Hillfort', 'https://en.wikipedia.org/wiki/Ham_Hill,_Somerset', 'fields-wd1-2026-09-26b-s009-rollback:d6ca1bdf-173c-4659-b1fc-c9fb7259c5a3:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Ham_Hill,_Somerset'' restored on Ham Hill, Somerset', '[{"source": "https://en.wikipedia.org/wiki/Ham_Hill_Hillfort", "url": "https://en.wikipedia.org/wiki/Ham_Hill_Hillfort", "quote": "Ham Hill Hillfort is an Iron Age hillfort located on Ham Hill, Somerset, England.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=4956", "url": "https://www.megalithic.co.uk/article.php?sid=4956", "quote": "Site Name: Ham Hill (Somerset) Alternative Name: Hamdon Hill", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0035)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about the hill as a whole (geology, SSSI, country park) and itself points to the main article ''Ham Hill Hillfort'', which is about this very site; the Megalithic Portal names the same hillfort.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Ham Hill Hillfort", "unreadable": false, "wikibase_item": "Q15222650"}}]'::jsonb),
    ('d6d67a37-3efa-44d4-9340-004a07a52ea8'::uuid, 'geom', 'SRID=4326;POINT(23.03611 37.61444)', '0101000020E61000003D39EA3B89083740EE106117D2CC4240', 'fields-wd1-2026-09-26b-s009-rollback:d6d67a37-3efa-44d4-9340-004a07a52ea8:geom', 'rollback of fields-wd1-2026-09-26b-s009: geom ''0101000020E61000003D39EA3B89083740EE106117D2CC4240'' restored on Lygourio', '[{"source": "https://el.wikipedia.org/wiki/%CE%9B%CF%85%CE%B3%CE%BF%CF%85%CF%81%CE%B9%CF%8C", "url": "https://el.wikipedia.org/wiki/%CE%9B%CF%85%CE%B3%CE%BF%CF%85%CF%81%CE%B9%CF%8C", "quote": "37.61444°N 23.03611°E", "outcome": "found"}, {"source": "https://www.geonames.org/258377", "url": "https://www.geonames.org/258377", "quote": "Coordinates 37.61233, 23.03773", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0067)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is Lygourio, the town that English Wikipedia places on the spot of ancient Lessa. Greek Wikipedia and GeoNames put the town at 37.614, 23.036 and 37.612, 23.038. The stored point comes from the English article''s minute-rounded coordinates (37°36′N 23°02′E) and lies about 1.6 km south of the town, so it is replaced.", "value_page": null}]'::jsonb),
