    ('d6d67a37-3efa-44d4-9340-004a07a52ea8'::uuid, 'period_name', NULL, '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s009-rollback:d6d67a37-3efa-44d4-9340-004a07a52ea8:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''500 BC - 1 AD'' restored on Lygourio', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d6d67a37-3efa-44d4-9340-004a07a52ea8'::uuid, 'period_start', NULL, '-500', 'fields-wd1-2026-09-26b-s009-rollback:d6d67a37-3efa-44d4-9340-004a07a52ea8:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-500'' restored on Lygourio', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0067)", "decision": "clear", "status": "MISSING", "reasoning": "No source dates when a site at Lygourio begins. Wikipedia says only that ancient Lessa, known from Pausanias, lay at or near the place, and ToposText gives Lessa''s location as uncertain (''possibly at Kazarma/Arkadiko or Ligourio''). The village''s first mention in the 14th century is a first attestation, not the site''s start, so the field is emptied.", "value_page": null}]'::jsonb),
    ('d7215ef3-51c2-4b04-9d35-126f058e0bf6'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Pyla-Kokkinokremos', 'https://en.wikipedia.org/wiki/Kokkinokremmos', 'fields-wd1-2026-09-26b-s009-rollback:d7215ef3-51c2-4b04-9d35-126f058e0bf6:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Kokkinokremmos'' restored on Kokkinokremmos', '[{"source": "https://en.wikipedia.org/wiki/Pyla-Kokkinokremos", "url": "https://en.wikipedia.org/wiki/Pyla-Kokkinokremos", "quote": "The site of Pyla-Kokkinokremos, located on a rocky plateau, lies about 10 km (6.2 mi) east of Larnaca and ancient Kition", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Pyla-Kokkinokremmos", "url": "https://de.wikipedia.org/wiki/Pyla-Kokkinokremmos", "quote": "Pyla-Kokkinokremmos (griechisch Πύλα-Κοκκινόκρεμμος) ist der Name eines archäologischen Fundorts im Südosten der Insel Zypern.", "outcome": "found"}, {"source": "https://site.minoan-aegis.net/field-projects/pyla-kokkinokremos", "url": "https://site.minoan-aegis.net/field-projects/pyla-kokkinokremos", "quote": "The Late Bronze Age settlement of Pyla-Kokkinokremos has, since its discovery in the early 1950s", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0003)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL en.wikipedia.org/wiki/Kokkinokremmos is only a redirect; the site''s own English Wikipedia article is Pyla-Kokkinokremos (the German article spells it Pyla-Kokkinokremmos), about this Late Bronze Age settlement near Pyla east of Larnaca, and the excavation project''s own page confirms the same site.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Pyla-Kokkinokremos", "unreadable": false, "wikibase_item": "Q6426672"}}]'::jsonb),
    ('d747c493-89ff-4471-ac39-17dbd5a5614c'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s009-rollback:d747c493-89ff-4471-ac39-17dbd5a5614c:period_name', 'rollback of fields-wd1-2026-09-26b-s009: period_name ''1500 - 500 BC'' restored on Ruins of Ténès', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('d747c493-89ff-4471-ac39-17dbd5a5614c'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s009-rollback:d747c493-89ff-4471-ac39-17dbd5a5614c:period_start', 'rollback of fields-wd1-2026-09-26b-s009: period_start ''-1500'' restored on Ruins of Ténès', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "clear", "status": "MISSING", "reasoning": "The only dated start is Wikipedia''s uncited ''Phoenician colony by the 8th century BC'' (repeated by sites copying it); the CNR Algeria Punica text and the Pauly-Wissowa entry attest a Punic mining town and an unpublished probably pre-Roman necropolis without a date, and the Augustan colony of c. 30 BC is not the start. No two independent sources date the start, and the stored 1500 BC has no support, so the field is emptied.", "value_page": null}]'::jsonb),
    ('d747c493-89ff-4471-ac39-17dbd5a5614c'::uuid, 'site_type', 'City', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26b-s009-rollback:d747c493-89ff-4471-ac39-17dbd5a5614c:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Necropolis/tombs complex'' restored on Ruins of Ténès', '[{"source": "https://en.wikipedia.org/wiki/Cartennae", "url": "https://en.wikipedia.org/wiki/Cartennae", "quote": "Ancient city in Mauretania Caesariensis", "outcome": "found"}, {"source": "http://afn.collections.free.fr/pages/tenes.html", "url": "http://afn.collections.free.fr/pages/tenes.html", "quote": "fut impressionné par l''importance des ruines de l''ancienne cité qui mesuraient 700 x 400m", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "replace", "status": "CONFLICT", "reasoning": "The ruins of Ténès are the remains of the Punic and Roman town of Cartennae (a colony under Augustus, ramparts, cisterns, necropolis); Wikipedia calls it an ancient city and the Ténès heritage page describes the ruins of the ancient city of 700 x 400 m. The necropolis is only one part of it, so the site as a whole is a City.", "value_page": null}]'::jsonb),
    ('d747c493-89ff-4471-ac39-17dbd5a5614c'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Cartennae', 'https://en.wikipedia.org/wiki/T%C3%A9n%C3%A8s', 'fields-wd1-2026-09-26b-s009-rollback:d747c493-89ff-4471-ac39-17dbd5a5614c:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/T%C3%A9n%C3%A8s'' restored on Ruins of Ténès', '[{"source": "https://en.wikipedia.org/wiki/Cartennae", "url": "https://en.wikipedia.org/wiki/Cartennae", "quote": "was an ancient Carthaginian and Roman port at present-day Ténès", "outcome": "found"}, {"source": "http://cherchel-project.isma.cnr.it/index.php?option=com_content&view=article&id=59&Itemid=44&lang=it", "url": "http://cherchel-project.isma.cnr.it/index.php?option=com_content&view=article&id=59&Itemid=44&lang=it", "quote": "Cartennas (l’attuale Ténès", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about the modern commune of Ténès; the English Wikipedia article Cartennae is about the ancient Carthaginian and Roman town whose ruins this is, and the CNR Algeria Punica project names the same Cartennas at present-day Ténès.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Cartennae", "unreadable": false, "wikibase_item": "Q15052636"}}]'::jsonb),
    ('d7b854ff-65ad-4131-a67a-a570af61d9e8'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s009-rollback:d7b854ff-65ad-4131-a67a-a570af61d9e8:site_type', 'rollback of fields-wd1-2026-09-26b-s009: site_type ''Fortress/citadel'' restored on Killerton', '[{"source": "https://en.wikipedia.org/wiki/Dolbury", "url": "https://en.wikipedia.org/wiki/Dolbury", "quote": "Dolbury is another local name for the Iron Age hill fort or enclosure at Killerton Park in Devon, England.", "outcome": "found"}, {"source": "https://www.devon.gov.uk/historicenvironment/explore-devons-heritage/dolbury-hillfort/", "url": "https://www.devon.gov.uk/historicenvironment/explore-devons-heritage/dolbury-hillfort/", "quote": "Dolbury Hillfort is a Scheduled Monument thought to date to the early Iron Age, around 600 BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0038)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and Devon County Council describe the ancient site at Killerton as Dolbury, an Iron Age hill fort (hillfort); the house itself is an 18th-century country house, and nothing calls the site a fortress or citadel, so the specific type is Fort.", "value_page": null}]'::jsonb),
    ('d7b854ff-65ad-4131-a67a-a570af61d9e8'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Dolbury', 'https://en.wikipedia.org/wiki/Killerton', 'fields-wd1-2026-09-26b-s009-rollback:d7b854ff-65ad-4131-a67a-a570af61d9e8:source_url', 'rollback of fields-wd1-2026-09-26b-s009: source_url ''https://en.wikipedia.org/wiki/Killerton'' restored on Killerton', '[{"source": "https://en.wikipedia.org/wiki/Dolbury", "url": "https://en.wikipedia.org/wiki/Dolbury", "quote": "Dolbury is another local name for the Iron Age hill fort or enclosure at Killerton Park in Devon, England.", "outcome": "found"}, {"source": "https://www.devon.gov.uk/historicenvironment/explore-devons-heritage/dolbury-hillfort/", "url": "https://www.devon.gov.uk/historicenvironment/explore-devons-heritage/dolbury-hillfort/", "quote": "Dolbury hillfort is thought to represent two phases of construction.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0038)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about Killerton House, the National Trust country house and estate; the ancient site is Dolbury hillfort in its park, which has its own English Wikipedia article, and Devon County Council''s page on Dolbury Hillfort places it within the grounds of Killerton House.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Dolbury", "unreadable": false, "wikibase_item": "Q5288888"}}]'::jsonb);
